window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[272]={"id":"272","numero":272,"titre":"Ulcère gastroduodénal - gastrite","objectifs":[{"id":"272-1","rang":"A","rubrique":"Définition","titre":"Connaître les définitions d'un ulcère gastrique ou duodénal","contenu":"<p>L'<strong>ulcère gastroduodénal</strong> (<span class=\"kw-clinique\">UGD</span>) résulte d'un <span class=\"kw-def\">déséquilibre entre l'agression chlorhydropeptique et les mécanismes de défense</span> de la muqueuse (barrière muqueuse), en <strong>un point précis</strong> de la paroi.</p>\n      <p>La <strong>barrière muqueuse</strong> de défense comporte <strong>trois lignes</strong> :</p>\n      <ul>\n        <li><span class=\"kw-def\">Pré-épithéliale</span> : mucus (barrière mécanique), sécrétion de phospholipides et de <span class=\"kw-bio\">bicarbonates</span> (tamponnement)</li>\n        <li><span class=\"kw-def\">Épithéliale</span> : cellules de surface assurant le renouvellement cellulaire</li>\n        <li><span class=\"kw-def\">Sous-épithéliale</span> : flux sanguin muqueux (vascularisation de la muqueuse)</li>\n      </ul>\n      <p><span class=\"kw-clinique\">Érosion</span>, ulcération et ulcère se distinguent par la <strong>profondeur</strong> de la perte de substance :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Lésion</span></th><th>Profondeur atteinte</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Érosion</span></td><td>Limitée à la <span class=\"kw-def\">muqueuse</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Ulcération</span></td><td>Limitée à la <span class=\"kw-def\">sous-muqueuse</span></td></tr>\n          <tr><td>Ulcère</td><td>Perte de substance de la paroi gastrique ou duodénale atteignant la <span class=\"kw-alerte\">musculeuse</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège — </strong><span class=\"kw-clinique\">érosion</span>, ulcération et ulcère ne sont pas synonymes : seule la <span class=\"kw-alerte\">profondeur atteinte</span> <span class=\"kw-clinique\">les</span> discrimine. Le terme « ulcère » impose une atteinte de la <span class=\"kw-alerte\">musculeuse</span>.</div>\n      <p><strong>Ulcère chronique <span class=\"kw-bio\">vs</span> aigu</strong> — l'ulcère chronique se distingue de l'ulcère aigu par l'existence d'un <span class=\"kw-def\">socle scléro-inflammatoire dans la musculeuse</span>, contenant des <strong>hyperplasies nerveuses</strong> et des lésions <span class=\"kw-def\">d'endartérite</span>.</p>\n      <p><strong>Localisations préférentielles :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Ulcère duodénal</span> : en plein bulbe ou à la pointe du bulbe (D1)</li>\n        <li><span class=\"kw-clinique\">Ulcère gastrique</span> : antre et petite courbure</li>\n      </ul>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/gastritis","label":"Radiopaedia : Gastritis"},{"href":"https://radiopaedia.org/articles/peptic-ulcer-disease","label":"Radiopaedia : Peptic ulcer disease"}]},{"id":"272-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence de l'ulcère gastrique ou duodénal","contenu":"<p>L'<span class=\"kw-def\">incidence</span> de l'<span class=\"kw-clinique\">UGD</span> est en <strong>régression</strong> dans <span class=\"kw-clinique\">les</span> pays développés, parallèlement au recul de l'infection gastrique à <span class=\"kw-etio\">H. pylori</span>.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Données</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Incidence</span></td><td>Pays développés <span class=\"kw-chiffre\">1 à 2 / 1000 / an</span> ; France <span class=\"kw-chiffre\">≈ 90 000 cas/an</span></td></tr>\n          <tr><td>Sex-ratio</td><td>Prédominance masculine <span class=\"kw-chiffre\">2 H / 1 F</span> (LISA) ; l'ancien référentiel ne retrouvait cette prédominance que pour l'<strong>ulcère duodénal</strong></td></tr>\n          <tr><td>Âge</td><td>Avant <span class=\"kw-chiffre\">55 ans</span>, l'ulcère duodénal est <span class=\"kw-chiffre\">3 à 4×</span> plus fréquent que l'ulcère gastrique</td></tr>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Patients avec <span class=\"kw-def\">comorbidités</span> cardiovasculaire, rénale, hépatique ou pancréatique ; <span class=\"kw-clinique\">les</span> ulcères du <span class=\"kw-alerte\">sujet âgé</span> sont volontiers compliqués</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Mortalité</span></strong> — le taux de mortalité des complications ulcéreuses (hémorragie, <span class=\"kw-def\">comorbidités</span> associées) est de <span class=\"kw-alerte\">2 à 10 %</span>. Un <span class=\"kw-chiffre\">tiers</span> des <span class=\"kw-clinique\">UGD</span> compliqués est attribuable aux <span class=\"kw-ttt\">AINS</span> ou à l'<span class=\"kw-ttt\">aspirine à faible dose</span>.</p>","frequence":0},{"id":"272-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le mécanisme des ulcères hémorragiques","contenu":"<p>L'hémorragie résulte de l'<span class=\"kw-def\">ulcération des vaisseaux de la paroi gastroduodénale</span>. En cas d'hémorragie <span class=\"kw-alerte\">sévère</span>, il s'agit le plus souvent de l'<span class=\"kw-clinique\">érosion</span> d'une artère, dont le siège dépend de la localisation de l'ulcère :</p>\n      <table >\n        <thead><tr><th>Siège de l'ulcère</th><th>Artère érodée</th></tr></thead>\n        <tbody>\n          <tr><td>Face postérieure du bulbe duodénal</td><td><span class=\"kw-alerte\">Artère gastro-duodénale</span></td></tr>\n          <tr><td>Petite courbure gastrique</td><td><span class=\"kw-alerte\">Artère gastrique gauche</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Cas particulier — <span class=\"kw-clinique\">ulcération</span> de Dieulafoy :</strong> <span class=\"kw-def\">ulcération muqueuse en regard d'une artère sous-muqueuse volumineuse</span>. Le diagnostic est difficile car l'artère n'est pas toujours apparente et le <span class=\"kw-alerte\">saignement abondant</span> gêne le geste d'hémostase.</p>\n      <p><strong><span class=\"kw-def\">Classification</span> de Forrest</strong> <span class=\"kw-def\">(Rang B)</span> — décrit l'aspect endoscopique de l'ulcère <span class=\"kw-etio\">hémorragique</span> ; elle est <strong>corrélée au risque de récidive hémorragique</strong> :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Aspect endoscopique</th></tr></thead>\n        <tbody>\n          <tr><td>I a</td><td><span class=\"kw-alerte\">Hémorragie en jet</span></td></tr>\n          <tr><td>I b</td><td>Suintement diffus</td></tr>\n          <tr><td>II a</td><td>Vaisseau visible, non <span class=\"kw-etio\">hémorragique</span></td></tr>\n          <tr><td>II b</td><td>Caillot adhérent</td></tr>\n          <tr><td>II c</td><td>Taches p<span class=\"kw-chiffre\">igm</span>entées</td></tr>\n          <tr><td>III a</td><td>Cratère à fond propre</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 355 — Hémorragie digestive</em></p>","frequence":3},{"id":"272-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les facteurs favorisants des formes compliquées des ulcères gastrique ou duodénal","contenu":"<p><strong><span class=\"kw-def\">Facteurs de risque</span> des ulcères compliqués</strong> — ils prédisposent à l'hémorragie et à la perforation :</p>\n      <ul>\n        <li><span class=\"kw-chiffre\">Âge > 65 ans</span></li>\n        <li><span class=\"kw-alerte\">ATCD d'UGD compliqué</span></li>\n        <li><span class=\"kw-ttt\">AINS</span> ou <span class=\"kw-ttt\">aspirine</span>, particulièrement en cas d'<span class=\"kw-etio\">infection à H. pylori</span> associée</li>\n        <li>Prise d'<span class=\"kw-ttt\">anticoagulant</span></li>\n      </ul>\n      <p><strong><span class=\"kw-ttt\">AINS</span> et <span class=\"kw-ttt\">aspirine</span></strong> — l'<span class=\"kw-def\">inhibition de la COX-1</span> (qui produit <span class=\"kw-clinique\">les</span> prostaglandines gastroduodénales) favorise les <span class=\"kw-clinique\">UGD</span> (plutôt <strong>gastriques</strong>) et leurs complications :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">AINS</span> : risque relatif <span class=\"kw-chiffre\">≈ 4</span></li>\n        <li><span class=\"kw-ttt\">Aspirine</span> : risque relatif <span class=\"kw-chiffre\">≈ 1,5</span> ; à dose anti-agrégante, elle ajoute une <span class=\"kw-alerte\">gastrotoxicité directe</span> et expose au <span class=\"kw-alerte\">risque hémorragique</span></li>\n        <li><span class=\"kw-ttt\">Coxibs</span> (anti-COX-2 préservant la COX-1) : réduisent le risque de complications de <span class=\"kw-chiffre\">≈ 50 %</span> sans le supprimer</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>❌ Piège — </strong><span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">corticoïdes</span> seuls ne sont <span class=\"kw-alerte\">pas ulcérogènes</span>.</div>\n      <p><strong><span class=\"kw-clinique\">Syndrome de Zollinger</span>-Ellison</strong> <span class=\"kw-def\">(rare)</span> — hypersécrétion acide liée à une <span class=\"kw-etio\">hypergastrinémie tumorale</span> (gastrinome, tumeur neuro-endocrine pancréatico-duodénale, <span class=\"kw-alerte\">maligne dans 50-60 %</span>) ; <span class=\"kw-chiffre\">sporadique dans 75 %</span> des cas, ou associé à une <span class=\"kw-etio\">NEM1</span>. Tableau : ulcères <span class=\"kw-alerte\">multiples, récidivants, souvent compliqués</span> + <span class=\"kw-clinique\">diarrhée chronique sécrétoire</span> améliorée sous <span class=\"kw-ttt\">IPP</span>.</p>\n      <p><strong>Autres facteurs d'agression</strong> (à rechercher devant un ulcère non lié à HP ni aux <span class=\"kw-ttt\">AINS</span>) :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Tabac</span></li>\n        <li><span class=\"kw-etio\">Maladie de Crohn</span>, <span class=\"kw-etio\">vascularites</span></li>\n        <li>Infections chez l'immunodéprimé : <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">CMV</span></li>\n        <li><span class=\"kw-alerte\">Stress pathologique intense</span> : <span class=\"kw-alerte\">réanimation</span>, grand brûlé</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Pièges pertinents — </strong>ne sont <span class=\"kw-alerte\">PAS</span> des <span class=\"kw-def\">facteurs de risque</span> d'<span class=\"kw-clinique\">UGD</span> : l'<span class=\"kw-alerte\">alcool</span>, le <span class=\"kw-alerte\">régime alimentaire</span>, le <span class=\"kw-alerte\">stress psychologique</span>. L'<span class=\"kw-etio\">alcool</span> est cependant pourvoyeur de gastropathie chimique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span> · 282 — <span class=\"kw-clinique\">MICI</span></em></p>","frequence":0},{"id":"272-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître l'importance d'Helicobacter pylori (HP) dans la récidive ulcéreuse","contenu":"<p><strong><span class=\"kw-clinique\">Helicobacter pylori</span></strong> — <span class=\"kw-def\">bacille à Gram négatif flagellé, spiralé</span>, doté d'une <span class=\"kw-def\">activité uréasique</span> qui lui permet de résister à l'acidité gastrique ; il colonise la muqueuse gastrique.</p>\n      <p><strong>Rôle dans la récidive ulcéreuse</strong> — l'<span class=\"kw-ttt\">éradication d'HP</span> est ce qui prévient la récidive de l'ulcère. Un <span class=\"kw-clinique\">UGD</span> associé à HP et <span class=\"kw-alerte\">non éradiqué récidive de façon quasi constante</span>.</p>\n      <p><strong>Profils sécréteurs et complications</strong> de la <span class=\"kw-clinique\">gastrite</span> chronique à HP :</p>\n      <table >\n        <thead><tr><th>Profil</th><th><span class=\"kw-clinique\">Évolution</span></th></tr></thead>\n        <tbody>\n          <tr><td>Hypersécréteur</td><td><span class=\"kw-clinique\">Gastrite</span> <span class=\"kw-clinique\">antrale peu atrophiante</span> → <span class=\"kw-clinique\">hyperchlorhydrie</span> → <span class=\"kw-alerte\">ulcère duodénal</span> (≈ <span class=\"kw-chiffre\">10 %</span>)</td></tr>\n          <tr><td>Hyposécréteur</td><td><span class=\"kw-clinique\">Atrophie</span> de la muqueuse → <span class=\"kw-bio\">achlorhydrie</span> → <span class=\"kw-alerte\">ulcère gastrique</span> (≈ <span class=\"kw-chiffre\">3 %</span>) ; séquence métaplasie intestinale (<span class=\"kw-chiffre\">40 %</span>) → dysplasie (<span class=\"kw-chiffre\">8 %</span>) → <span class=\"kw-etio\">adénocarcinome gastrique</span> (<span class=\"kw-chiffre\">1-3 %</span>)</td></tr>\n        </tbody>\n      </table>\n      <p>Dans le contexte de l'infection à HP, à prédominance antrale, <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">ulcères duodénaux sont 3 à 4× plus fréquents</span> que les ulcères gastriques.</p>\n      <div class=\"callout callout-info\"><strong>Pierre angulaire — </strong>l'<span class=\"kw-ttt\">éradication d'H. pylori</span> est la mesure de prévention de la récidive ulcéreuse.</div>","frequence":0},{"id":"272-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques/sémiologie de la douleur de l'ulcère","contenu":"<p>Le diagnostic d'ulcère est <strong>évoqué</strong> sur la sémiologie douloureuse, mais n'est jamais affirmé sur <span class=\"kw-clinique\">les</span> seuls symptômes.</p>\n      <p><strong><span class=\"kw-clinique\">Syndrome ulcéreux</span> typique</strong> — <span class=\"kw-clinique\">douleur épigastrique</span> à type de <span class=\"kw-clinique\">crampe</span>, de <span class=\"kw-clinique\">torsion</span> ou de <span class=\"kw-clinique\">faim douloureuse</span> :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Sans irradiation</span></li>\n        <li><span class=\"kw-clinique\">Calmée par la prise d'aliments</span>, d'anti-acides et de pansements gastriques</li>\n        <li><strong>Double périodicité :</strong> dans la journée, douleur <span class=\"kw-clinique\">post-prandiale tardive</span> (<span class=\"kw-chiffre\">1 à 3 h</span> après <span class=\"kw-clinique\">les</span> repas) ; dans l'année, poussées de quelques <span class=\"kw-chiffre\">semaines</span> séparées par des intervalles asymptomatiques de quelques <span class=\"kw-chiffre\">mois à années</span></li>\n      </ul>\n      <p><strong>Syndrome douloureux atypique :</strong></p>\n      <ul>\n        <li>Localisation variable : <span class=\"kw-clinique\">hypochondre droit ou gauche</span>, <span class=\"kw-clinique\">irradiation</span> <span class=\"kw-clinique\">dorsale ou strictement postérieure</span></li>\n        <li>Intensité variable : forme hyperalgique pseudo-chirurgicale, ou au contraire simple gêne frustre</li>\n        <li><span class=\"kw-alerte\">Absence de périodicité</span>, douleur <span class=\"kw-alerte\">non rythmée par l'alimentation</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège — </strong>le syndrome douloureux <span class=\"kw-alerte\">atypique est plus fréquent</span> que la forme typique.</div>\n      <p><strong>Examen clinique</strong> — <span class=\"kw-clinique\">normal</span> en l'absence de complication.</p>\n      <p><strong>Autres circonstances de découverte :</strong></p>\n      <ul>\n        <li>Forme <span class=\"kw-clinique\">asymptomatique / fortuite</span> (<span class=\"kw-clinique\">UGD</span> révélé par une <span class=\"kw-imagerie\">endoscopie</span> faite pour une autre raison) : jusqu'à <span class=\"kw-chiffre\">2/3</span> des cas selon certaines études</li>\n        <li>Complication inaugurale : <span class=\"kw-alerte\">hémorragie ou perforation</span> d'emblée, sans signe d'alarme ; <span class=\"kw-alerte\">sténose</span> révélée par des <span class=\"kw-clinique\">vomissements</span> post-prandiaux</li>\n      </ul>","frequence":2},{"id":"272-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications de l'endoscopie haute devant une douleur ulcéreuse","contenu":"<div class=\"callout callout-info\"><strong><span class=\"kw-imagerie\">EOGD</span> — </strong>l'<span class=\"kw-imagerie\">endoscopie</span> digestive haute <strong>affirme le diagnostic</strong> d'ulcère, qui ne peut pas reposer sur <span class=\"kw-clinique\">les</span> seuls symptômes. Elle élimine les diagnostics différentiels (cancer +++ si ulcère gastrique) et permet les biopsies.</div>\n      <p><strong>Indications de l'<span class=\"kw-imagerie\">EOGD</span></strong> devant une douleur ulcéreuse (identiques au <span class=\"kw-clinique\">RGO</span>) :</p>\n      <ul>\n        <li><span class=\"kw-chiffre\">Âge > 50 ans</span></li>\n        <li>OU présence de <span class=\"kw-alerte\">signes d'alarme</span> : <span class=\"kw-clinique\">dysphagie</span>, <span class=\"kw-clinique\">amaigrissement</span>, hémorragie digestive, anémie</li>\n        <li>OU inefficacité du traitement symptomatique de 1re intention</li>\n      </ul>\n      <p><strong>Modalités</strong> — anesthésie <span class=\"kw-clinique\">locale pharyngée</span> ou générale (l'anesthésie générale n'est <span class=\"kw-alerte\">pas nécessaire</span>) ; morbi-<span class=\"kw-def\">mortalité</span> faible.</p>\n      <p><strong>Aspect endoscopique de l'ulcère</strong> — perte de substance profonde « <span class=\"kw-radio\">creusante</span> », fond <span class=\"kw-radio\">pseudo-membraneux blanchâtre</span> parfois nécrotique, <span class=\"kw-clinique\">lésion</span> ronde ou ovalaire à bords réguliers, surélevés et érythémateux.</p>\n      <div class=\"callout callout-warn\"><strong>Piège — </strong>un <span class=\"kw-alerte\">ulcère duodénal post-bulbaire</span> (très rare) doit faire évoquer un <span class=\"kw-etio\">syndrome de Zollinger-Ellison</span> ou une <span class=\"kw-etio\">MICI</span> (Crohn, <span class=\"kw-clinique\">vascularite</span>).</div>\n      <p><strong>Conduite biopsique selon le siège :</strong></p>\n      <table >\n        <thead><tr><th>Siège</th><th>Biopsies</th></tr></thead>\n        <tbody>\n          <tr><td>Ulcère duodénal</td><td><span class=\"kw-alerte\">Pas de biopsie de la lésion duodénale</span> ; biopsies gastriques (antre, angle, fundus) pour la <span class=\"kw-clinique\">gastrite</span> à HP ; pas de contrôle endoscopique si patient asymptomatique, sauf UD compliqué</td></tr>\n          <tr><td>Ulcère gastrique</td><td>Biopsies gastriques HP + <span class=\"kw-chiffre\">6 à 12 biopsies des berges</span> de l'ulcère, recherchant un <span class=\"kw-etio\">adénocarcinome</span> voire un <span class=\"kw-etio\">lymphome</span> ; <span class=\"kw-imagerie\">fibroscopie de contrôle</span> après traitement (zone cicatricielle + recherche d'HP)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Systématique — </strong>la <span class=\"kw-alerte\">recherche d'H. pylori</span> est systématique devant tout <span class=\"kw-clinique\">UGD</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale · 303 — Tumeur estomac</em></p>","frequence":1},{"id":"272-8","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir prescrire une recherche d'HP (tests invasifs et non invasifs)","contenu":"<p><strong>Indications de la recherche d'<span class=\"kw-clinique\">H. pylori</span> :</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\">Systématique</span> devant tout <span class=\"kw-clinique\">UGD</span> et tout cancer de l'estomac</li>\n        <li>FR de cancer gastrique : apparenté du 1er degré, <span class=\"kw-clinique\">syndrome de Lynch</span> (HNPCC), ATCD de gastrectomie partielle, lésions prénéoplasiques (atrophie sévère, métaplasie intestinale, dysplasie)</li>\n        <li>HAS : avant <span class=\"kw-ttt\">AINS</span> ou <span class=\"kw-ttt\">aspirine</span> si ATCD d'<span class=\"kw-clinique\">UGD</span> ; <span class=\"kw-bio\">carence martiale inexpliquée</span> ; <span class=\"kw-bio\">carence en B12 sans cause</span> ; lymphome gastrique du MALT ; avant by-pass gastrique ; PTI de l'adulte</li>\n      </ul>\n      <p><strong>Méthodes de recherche :</strong></p>\n      <table >\n        <thead><tr><th>Test</th><th>Performance</th><th>Principe & utilité</th></tr></thead>\n        <tbody>\n          <tr><td>Test invasif (biopsies)</td><td>Se & Sp <span class=\"kw-chiffre\">> 95 %</span></td><td>Biopsies gastriques <span class=\"kw-alerte\">antrales et fundiques</span> — <span class=\"kw-bio\">anatomopathologie</span> (le plus utilisé), culture + <span class=\"kw-bio\">antibiogramme</span>, <span class=\"kw-bio\">PCR</span>. Examen de <strong>référence</strong></td></tr>\n          <tr><td>Test respiratoire à l'<span class=\"kw-bio\">urée</span> marquée (C13)</td><td>Se & Sp <span class=\"kw-chiffre\">> 95 %</span></td><td><span class=\"kw-bio\">Urée</span> marquée ingérée puis CO2 expiré mesuré ; validé surtout pour le <span class=\"kw-bio\">contrôle d'éradication</span> ; seul test remboursé pour le contrôle</td></tr>\n          <tr><td>Antigènes fécaux</td><td>Se <span class=\"kw-chiffre\">91-96 %</span> / Sp <span class=\"kw-chiffre\">93-97 %</span></td><td>Antigènes d'HP détectés dans <span class=\"kw-clinique\">les</span> selles ; performant avant traitement et pour le contrôle, mais <strong>non remboursé</strong></td></tr>\n          <tr><td><span class=\"kw-bio\">Sérologie</span></td><td>Se <span class=\"kw-chiffre\">85 %</span> / Sp <span class=\"kw-chiffre\">79 %</span></td><td>Utile si <span class=\"kw-alerte\">hémorragie</span> (pas de <span class=\"kw-ttt\">biopsie</span> possible), atrophie gastrique ou ATB récent ; <span class=\"kw-alerte\">reste positive après éradication</span> → inutile pour le contrôle</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Piège — </strong><span class=\"kw-alerte\">jamais de biopsies duodénales</span> pour la recherche d'HP : seules <span class=\"kw-clinique\">les</span> biopsies gastriques antrales et fundiques sont valides.</div>\n      <div class=\"callout callout-warn\"><strong>Annale — </strong>devant un <span class=\"kw-alerte\">ulcère hémorragique</span>, c'est la <span class=\"kw-bio\">sérologie</span> qui est indiquée (<span class=\"kw-clinique\">les</span> biopsies ne sont pas réalisables en période <span class=\"kw-etio\">hémorragique</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 303 — Tumeur estomac</em></p>","frequence":3},{"id":"272-9","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir reconnaître les signes de gravité d'une douleur ulcéreuse","contenu":"<div class=\"callout callout-warn\"><strong>Pas de parallélisme anatomo-clinique — </strong>il n'existe <span class=\"kw-alerte\">aucun critère de gravité de la douleur ulcéreuse</span> elle-même ; l'intensité de la douleur ne préjuge pas de la gravité.</div>\n      <p>On recherche <span class=\"kw-clinique\">les</span> <strong>signes associés à une complication</strong> :</p>\n      <table >\n        <thead><tr><th>Complication évoquée</th><th>Signes à rechercher</th></tr></thead>\n        <tbody>\n          <tr><td>Perforation</td><td><span class=\"kw-clinique\">Défense</span> ou <span class=\"kw-clinique\">contracture abdominale</span></td></tr>\n          <tr><td>Cancer</td><td><span class=\"kw-alerte\">Amaigrissement</span>, <span class=\"kw-clinique\">adénopathie sus-claviculaire</span> (ganglion de Troisier)</td></tr>\n          <tr><td>Hémorragie</td><td><span class=\"kw-clinique\">Chute tensionnelle</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-alerte\">hématémèse / méléna</span>, sang au toucher rectal</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"272-10","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les principales complications de l'ulcère","contenu":"<p>L'<span class=\"kw-clinique\">UGD</span> peut se compliquer de quatre façons :</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Hémorragie digestive</span></td><td>La <strong>plus fréquente</strong>, parfois inaugurale ; <span class=\"kw-chiffre\">30-40 %</span> des hémorragies digestives hautes ; <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">≈ 10 %</span></td></tr>\n          <tr><td>Perforation</td><td>Moins fréquente que l'hémorragie ; favorisée par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AINS</span></td></tr>\n          <tr><td>Sténose</td><td><span class=\"kw-def\">Exceptionnelle</span> ; complique <span class=\"kw-clinique\">les</span> ulcères bulbaires et pré-pyloriques ; <span class=\"kw-clinique\">vomissements post-prandiaux tardifs</span> ; risque d'<span class=\"kw-bio\">alcalose métabolique hypochlorémique hypokaliémique</span></td></tr>\n          <tr><td>Dégénérescence</td><td><span class=\"kw-alerte\">Ulcère gastrique uniquement</span> — l'ulcère duodénal ne dégénère jamais</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 355 — Hémorragie digestive · 357 — <span class=\"kw-clinique\">Péritonite</span> aiguë</em></p>","frequence":1},{"id":"272-11","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître la stratégie à adopter devant une hématémèse","contenu":"<p><strong>Évaluation de la gravité</strong> — la <span class=\"kw-clinique\">tachycardie</span> est le meilleur signe précoce de <span class=\"kw-alerte\">défaillance</span> hémodynamique. <span class=\"kw-alerte\">Signes de gravité</span> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">FC > 100 bpm</span> ; la <span class=\"kw-alerte\">bradycardie</span> est un <span class=\"kw-alerte\">signe de gravité</span> extrême ; <span class=\"kw-clinique\">hypotension</span> artérielle</li>\n        <li>Signes d'hypoperfusion : <span class=\"kw-clinique\">marbrures</span>, allongement du TRC, oligurie <span class=\"kw-chiffre\">< 0,5 mL/kg/h</span>, troubles de conscience</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Pièges (annale) — </strong>la <span class=\"kw-alerte\">quantité de sang extériorisé</span> est un mauvais critère de gravité ; l'<span class=\"kw-bio\">hémoglobine / hématocrite</span> peut sous-estimer initialement l'hémorragie ; le sujet jeune compense longtemps par une tachycardie.</div>\n      <p><strong>Premières mesures :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">2 voies veineuses périphériques</span>, oxygénation, scope (<span class=\"kw-bio\">SaO2</span>, pouls, PA, diurèse)</li>\n        <li>Bilan : <span class=\"kw-bio\">NFS, ionogramme, créatinine, calcémie, hémostase, 2 groupages + RAI</span> ± <span class=\"kw-bio\">gaz du sang</span></li>\n        <li>Arrêt et antagonisation des anticoagulants</li>\n      </ul>\n      <p><strong>Orientation</strong> — patient stable : service conventionnel ; patient instable, saignement actif ou <span class=\"kw-alerte\">état de choc</span> : <span class=\"kw-alerte\">USI / réanimation</span>.</p>\n      <p><strong>SNG</strong> — à <span class=\"kw-alerte\">éviter</span> en cas de suspicion de varices œsophagiennes ; discutée si vomissements incoercibles ou troubles de conscience.</p>\n      <p><strong>Choc hémorragique</strong> — remplissage par cristalloïdes ± <span class=\"kw-ttt\">noradrénaline</span> (si PAS < 80 mmHg malgré 1 à 1,5 L) ± transfusion. Cibles : <span class=\"kw-chiffre\">FC < 100 bpm</span>, <span class=\"kw-chiffre\">PAS > 100 mmHg</span> ou PAM ≥ 65, diurèse <span class=\"kw-chiffre\">> 0,5 mL</span>/kg/h, <span class=\"kw-chiffre\">Hb 7-9 g/dL</span> (7-8 si varices, > 9 si comorbidités cardiovasculaires).</p>\n      <p><strong>Traitement spécifique</strong> — <span class=\"kw-ttt\">IPP en IVSE</span> dès l'admission sans retarder l'<span class=\"kw-imagerie\">endoscopie</span> ; <span class=\"kw-imagerie\">EOGD</span> diagnostique, pronostique (Forrest) et thérapeutique ; <span class=\"kw-ttt\">hémostase endoscopique</span> (thermocoagulation / clips ± sérum adrénaliné) pour les stades Forrest Ia à IIb ; embolisation ou chirurgie en cas d'échec.</p>\n      <ul>\n        <li>Forrest <span class=\"kw-chiffre\">Ia à IIb</span> (signes endoscopiques de gravité) : <span class=\"kw-ttt\">IPP fortes doses en IV continu pendant 48-72 h</span>, puis relais per os à pleine dose</li>\n        <li>Forrest <span class=\"kw-chiffre\">IIc à III</span> (pas de signe endoscopique de gravité) : relais précoce par <span class=\"kw-ttt\">IPP pleine dose per os</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 355 — Hémorragie digestive</em></p>","frequence":1},{"id":"272-12","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les mesures à mettre en œuvre dans les formes perforées","contenu":"<p><strong>Perforation en péritoine libre = <span class=\"kw-clinique\">péritonite</span> :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Douleur épigastrique en coup de poignard</span>, à début <span class=\"kw-alerte\">brutal</span> (ce qui la distingue de la <span class=\"kw-clinique\">pancréatite aiguë</span>), diffusant ensuite à tout l'abdomen</li>\n        <li><span class=\"kw-alerte\">Contracture abdominale</span>, Douglas douloureux au toucher rectal, signes de <span class=\"kw-alerte\">choc</span></li>\n        <li><span class=\"kw-clinique\">Tympanisme et disparition de la matité préhépatique</span> = pneumopéritoine (signe quasi-pathognomonique)</li>\n      </ul>\n      <p><strong>Signes négatifs</strong> — <span class=\"kw-alerte\">pas de fièvre</span> et <span class=\"kw-alerte\">pas d'hyperleucocytose</span> durant <span class=\"kw-clinique\">les</span> premières heures (<span class=\"kw-clinique\">péritonite</span> chimique).</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> — </strong><span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée en 1re intention</span> (pneumopéritoine + <span class=\"kw-radio\">réaction inflammatoire</span> antro-pyloro-bulbaire). L'<span class=\"kw-ci\">endoscopie est formellement contre-indiquée</span>. Prise en charge d'une <span class=\"kw-clinique\">péritonite</span> secondaire : urgence chirurgicale + <span class=\"kw-ttt\">antibiothérapie</span> probabiliste.</div>\n      <p><strong>Facteurs favorisants</strong> — <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AINS</span> favorisent la perforation ; les <span class=\"kw-ttt\">corticoïdes</span> ne la favorisent pas mais <span class=\"kw-alerte\">retardent le diagnostic</span> en atténuant les signes cliniques.</p>\n      <p><strong>Ulcère perforé-bouché</strong> (perforation au <span class=\"kw-def\">contact</span> du pancréas) — <span class=\"kw-clinique\">régression de la douleur initiale</span>, <span class=\"kw-alerte\">pas de pneumopéritoine</span> (possible rétro-pneumopéritoine) ; méthode de Taylor (SNG en aspiration + <span class=\"kw-ttt\">IPP</span> + <span class=\"kw-ttt\">antibiotiques</span>) possible en l'absence de <span class=\"kw-alerte\">signe de gravité</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 357 — <span class=\"kw-clinique\">Péritonite</span> aiguë</em></p>","frequence":3},{"id":"272-13","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître l'examen de première intention devant une contracture abdominale","contenu":"<p>Devant une <span class=\"kw-clinique\">contracture abdominale</span> faisant suspecter une perforation d'ulcère :</p>\n      <div class=\"callout callout-danger\"><strong>Examen de 1re intention — </strong><span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span> : elle recherche un <span class=\"kw-radio\">pneumopéritoine</span> et une <span class=\"kw-radio\">réaction inflammatoire</span> de la région antro-pyloro-bulbaire. L'<span class=\"kw-ci\">endoscopie est contre-indiquée</span> de façon absolue en cas de perforation.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 357 — <span class=\"kw-clinique\">Péritonite</span> aiguë</em></p>","frequence":1},{"id":"272-14","rang":"B","rubrique":"Suivi et / ou pronostic","titre":"Connaître le risque dégénérescence des ulcères selon leur localisation","contenu":"<p>Le <strong>risque de dégénérescence</strong> dépend strictement de la localisation de l'ulcère :</p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Risque de cancérisation</th></tr></thead>\n        <tbody>\n          <tr><td>Ulcère duodénal</td><td>L'ulcère duodénal <span class=\"kw-alerte\">n'est jamais un cancer et ne se cancérise jamais</span></td></tr>\n          <tr><td>Ulcère gastrique</td><td>L'UG et l'<span class=\"kw-etio\">adénocarcinome gastrique</span> surviennent tous deux sur une <span class=\"kw-alerte\">muqueuse atrophique</span> (<span class=\"kw-def\">condition précancéreuse</span>) ; un <span class=\"kw-etio\">cancer débutant</span> peut mimer un UG bénin</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Conséquence pratique — </strong>la découverte d'un <span class=\"kw-alerte\">ulcère gastrique</span> impose des <span class=\"kw-imagerie\">biopsies des berges</span> (6 à 12) en plus des biopsies de l'antre et du fundus, à la recherche d'un cancer et de <span class=\"kw-def\">lésions précancéreuses</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 303 — Tumeur estomac</em></p>","frequence":1},{"id":"272-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","contenu":"<p><strong>Objectifs du traitement</strong> — suppression rapide des symptômes, <span class=\"kw-def\">cicatrisation</span>, prévention des récidives et des complications. La cicatrisation requiert un <span class=\"kw-chiffre\">pH gastrique > 3</span> :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">IPP demi-dose</span> (dose préventive) : suffit à cicatriser et à prévenir <span class=\"kw-clinique\">les</span> ulcères</li>\n        <li><span class=\"kw-ttt\">IPP pleine dose</span> (dose curative = 2× la demi-dose) : accélère la cicatrisation</li>\n      </ul>\n      <p><strong>Traitement de l'ulcère non compliqué — cas général :</strong></p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td>Ulcère gastrique</td><td><span class=\"kw-ttt\">IPP simple dose</span> pendant <span class=\"kw-chiffre\">4 à 8 semaines</span> + <span class=\"kw-imagerie\">contrôle endoscopique systématique</span> de la cicatrisation avec biopsies</td></tr>\n          <tr><td>Ulcère duodénal</td><td><span class=\"kw-ttt\">IPP simple dose</span> pendant <span class=\"kw-chiffre\">4 semaines</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-clinique\">UGD</span> associé à H. pylori</strong> <span class=\"kw-def\">(tombé en annale)</span> — trois temps :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">IPP simple dose</span> dès le diagnostic d'<span class=\"kw-clinique\">UGD</span>, en attendant le résultat de la recherche d'HP</li>\n        <li>Traitement d'<span class=\"kw-ttt\">éradication d'HP</span> : <span class=\"kw-ttt\">IPP double dose + antibiotiques</span> pendant <span class=\"kw-chiffre\">10 à 14 jours</span></li>\n        <li>Après éradication : <strong>pas d'<span class=\"kw-ttt\">IPP</span> au long cours</strong> si UD non compliqué ; <span class=\"kw-ttt\">IPP curatif 6 semaines</span> si UG ou UD compliqué, poursuite d'<span class=\"kw-ttt\">AINS</span>/anti-thrombotiques ou douleurs ép<span class=\"kw-chiffre\">iga</span>striques persistantes ; puis <span class=\"kw-ttt\">IPP préventif</span> selon la poursuite d'<span class=\"kw-ttt\">AINS</span>/<span class=\"kw-ttt\">aspirine</span></li>\n      </ul>\n      <p><strong><span class=\"kw-clinique\">UGD</span> induits par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AINS</span> ou l'<span class=\"kw-ttt\">aspirine</span></strong> — traitement standard de l'UGD + maintien d'un <span class=\"kw-ttt\">IPP</span> si l'<span class=\"kw-ttt\">AINS</span> ou l'<span class=\"kw-ttt\">aspirine</span> reste indispensable. <span class=\"kw-ttt\">IPP préventif</span> indiqué si : <span class=\"kw-chiffre\">âge > 65 ans</span>, ATCD d'UGD, traitement anti-<span class=\"kw-etio\">thrombotique</span> associé ou <span class=\"kw-ttt\">corticoïdes</span> associés.</p>\n      <p><strong><span class=\"kw-clinique\">UGD</span> non liés à HP ni aux <span class=\"kw-ttt\">AINS</span></strong> — éliminer d'abord un <span class=\"kw-etio\">Zollinger-Ellison</span>, une <span class=\"kw-etio\">maladie de Crohn</span>, un <span class=\"kw-etio\">lymphome</span>, un <span class=\"kw-etio\">cancer gastrique</span>.</p>\n      <p><strong>Focus — <span class=\"kw-ttt\">inhibiteurs de la pompe à protons</span> (<span class=\"kw-ttt\">IPP</span>)</strong> :</p>\n      <table >\n        <thead><tr><th>Dosage</th><th>Indications principales</th></tr></thead>\n        <tbody>\n          <tr><td>Demi-dose</td><td><span class=\"kw-clinique\">UGD</span> compliqué ou non devant poursuivre un <span class=\"kw-ttt\">AINS</span> ; ulcère compliqué devant poursuivre l'<span class=\"kw-ttt\">aspirine</span></td></tr>\n          <tr><td>Pleine dose</td><td>Ulcère gastrique (<span class=\"kw-chiffre\">4-8 sem</span>) ; ulcère duodénal (<span class=\"kw-chiffre\">4 sem</span>)</td></tr>\n          <tr><td>Double dose</td><td>Éradication d'<span class=\"kw-clinique\">H. pylori</span> ; hémorragie ulcéreuse ; sténose peptique</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Prise :</strong> à <span class=\"kw-clinique\">jeun, le matin, 15 à 30 min avant le repas</span></li>\n        <li><strong>Chez l'enfant :</strong> < 1 an pas d'AMM sauf œsophagite ; 1-12 ans <span class=\"kw-ttt\"><span class=\"kw-ttt\">oméprazole</span> / <span class=\"kw-ttt\">ésoméprazole</span></span> ; <span class=\"kw-chiffre\">> 12 ans</span> <span class=\"kw-ttt\">pantoprazole</span></li>\n        <li><strong>Effets indésirables</strong> (peu fréquents) : <span class=\"kw-clinique\">céphalées</span>, diarrhée, vertiges ; sur-risque d'<span class=\"kw-alerte\">infections digestives</span> (Salmonelles, <span class=\"kw-etio\">C. difficile</span>, Campylobacter), d'<span class=\"kw-alerte\">infection du liquide d'<span class=\"kw-clinique\">ascite</span></span> chez le cirrhotique, ostéoporose / fractures</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>❌ — </strong><span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">IPP</span> ne sont <span class=\"kw-alerte\">pas associés à la survenue de cancers</span>.</div>\n      <p><strong>Schémas d'éradication d'<span class=\"kw-clinique\">H. pylori</span></strong> — la <strong>quadrithérapie</strong> est privilégiée du fait du <span class=\"kw-alerte\">fort taux de résistance à la clarithromycine</span> en France ; éradication <span class=\"kw-chiffre\">≈ 90 %</span> :</p>\n      <table >\n        <thead><tr><th>Schéma</th><th>Molécules & durée</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td>Quadrithérapie bismuthée</td><td><span class=\"kw-ttt\">Métronidazole + tétracycline + oméprazole double dose + sous-citrate de bismuth</span> — <span class=\"kw-chiffre\">10 jours</span></td><td><span class=\"kw-ci\">Allergie</span> aux β-lactamines ; sensibilités non connues ; résistance à la <span class=\"kw-ttt\">clarithromycine</span> et à la <span class=\"kw-ttt\">lévofloxacine</span></td></tr>\n          <tr><td>Quadrithérapie concomitante</td><td><span class=\"kw-ttt\">Métronidazole + amoxicilline + clarithromycine + IPP double dose</span> — <span class=\"kw-chiffre\">14 jours</span></td><td>Sensibilités non connues, sans <span class=\"kw-ci\">allergie</span> aux β-lactamines</td></tr>\n          <tr><td><span class=\"kw-ttt\">Trithérapie</span> concomitante</td><td><span class=\"kw-ttt\">Amoxicilline + IPP double dose + clarithromycine</span> (ou <span class=\"kw-ttt\">lévofloxacine</span> si résistance) — <span class=\"kw-chiffre\">10 jours</span></td><td>Sensibilité connue, sans <span class=\"kw-ci\">allergie</span> aux β-lactamines</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Contrôle d'éradication</strong> — <span class=\"kw-alerte\">systématique</span> (≈ <span class=\"kw-chiffre\">10 %</span> d'échec en 1re ligne), réalisé <span class=\"kw-chiffre\">4 semaines après la fin des antibiotiques</span> et <span class=\"kw-chiffre\">2 semaines après l'arrêt des IPP</span> :</p>\n      <ul>\n        <li>UD ou <span class=\"kw-def\">dépistage</span> : <span class=\"kw-bio\">test respiratoire à l'urée marquée</span></li>\n        <li>UG : <span class=\"kw-imagerie\">contrôle endoscopique impératif</span> (biopsies de la zone cicatricielle)</li>\n        <li>Échec : switch de schéma sans <span class=\"kw-imagerie\">EOGD</span> puis nouveau contrôle ; en cas de nouvel échec, <span class=\"kw-imagerie\">EOGD</span> + biopsies avec étude de la sensibilité aux antibiotiques</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":5},{"id":"272-16","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'une gastrite","contenu":"<p><strong><span class=\"kw-clinique\">Gastrite</span></strong> — <span class=\"kw-def\">lésions inflammatoires aiguës ou chroniques de la muqueuse gastrique</span>. C'est un diagnostic <strong>histologique</strong> : <span class=\"kw-chiffre\">5 biopsies</span> sont recommandées pour le diagnostic (<span class=\"kw-chiffre\">2 fundus, 2 antre, 1 angle de la petite courbure</span>).</p>\n      <p><strong>Gastropathie</strong> — <span class=\"kw-def\">affection diffuse de la muqueuse gastrique sans infiltrat inflammatoire</span> ; à distinguer de la <span class=\"kw-clinique\">gastrite</span>.</p>\n      <div class=\"callout callout-warn\"><strong>❌ Pas de corrélation — </strong>aucune corrélation entre l'<span class=\"kw-alerte\">histologie et la symptomatologie</span>, ni entre l'<span class=\"kw-alerte\">histologie et l'aspect endoscopique</span>. « <span class=\"kw-clinique\">Gastrite</span> » est un <span class=\"kw-def\">diagnostic histologique</span> : on n'en parle ni pour décrire des symptômes, ni pour décrire des <span class=\"kw-radio\">lésions endoscopiques</span>.</div>","frequence":0},{"id":"272-17","rang":"B","rubrique":"Définition","titre":"Connaître les principaux types de gastrite","contenu":"<p>La <strong><span class=\"kw-def\">classification</span> de Sydney</strong> repose sur trois caractéristiques principales :</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>Étiologie</td><td>La cause de la <span class=\"kw-clinique\">gastrite</span></td></tr>\n          <tr><td>Topographie</td><td><span class=\"kw-clinique\">Gastrite</span> <span class=\"kw-clinique\">fundique</span> (maladie de Biermer) ou <span class=\"kw-clinique\">antrale</span> (<span class=\"kw-clinique\">H. pylori</span>)</td></tr>\n          <tr><td>Morphologie</td><td>Siège et densité de l'infiltrat <span class=\"kw-etio\">inflammatoire</span>, caractère <span class=\"kw-def\">actif</span> (PNN présents) ou inactif, degré d'atrophie muqueuse et de métaplasie intestinale, présence d'agents pathogènes</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Principaux types de <span class=\"kw-clinique\">gastrite</span> :</strong></p>\n      <table >\n        <thead><tr><th>Type</th><th>Caractéristique</th></tr></thead>\n        <tbody>\n          <tr><td>À <span class=\"kw-clinique\">H. pylori</span></td><td>De loin la <strong>plus fréquente</strong> ; topographie <span class=\"kw-clinique\">antrale</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Auto-immune</span> (Biermer)</td><td>Topographie <span class=\"kw-clinique\">fundique</span> ; atrophie progressive des glandes du fundus</td></tr>\n          <tr><td>Lymphocytaire</td><td>Association possible à une <span class=\"kw-etio\">maladie cœliaque</span>, une <span class=\"kw-etio\">colite lymphocytaire</span> ou une <span class=\"kw-etio\">infection à H. pylori</span></td></tr>\n          <tr><td>À collagène</td><td><span class=\"kw-def\">Bande de collagène sous-épithéliale</span> ; rare ; association possible à une <span class=\"kw-etio\">colite collagène</span> ou une <span class=\"kw-etio\">maladie cœliaque</span></td></tr>\n          <tr><td>Granulomateuse</td><td><span class=\"kw-etio\">Crohn, sarcoïdose, tuberculose, syphilis</span>, parasites</td></tr>\n          <tr><td>À <span class=\"kw-bio\">éosinophiles</span></td><td><span class=\"kw-etio\">Allergie alimentaire, parasitose</span> (anisakiase)</td></tr>\n          <tr><td><span class=\"kw-etio\">Virale</span></td><td><span class=\"kw-etio\">CMV, HSV</span> ; surtout l'immunodéprimé</td></tr>\n          <tr><td>Phlegmoneuse</td><td><span class=\"kw-etio\">Infection bactérienne</span> sévère de la paroi gastrique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Gastropathies</strong> (≠ <span class=\"kw-clinique\">gastrite</span>, sans infiltrat <span class=\"kw-etio\">inflammatoire</span>) : induite par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AINS</span> ; chimique (<span class=\"kw-etio\">alcool</span>, reflux biliaire post-gastrectomie) ; congestive (<span class=\"kw-clinique\">HTP</span>, ectasies vasculaires antrales) ; hypertrophique (maladie de Ménétrier) ; radique.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 282 — <span class=\"kw-clinique\">MICI</span></em></p>","frequence":1},{"id":"272-18","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les causes de la gastrite","contenu":"<p><strong>Rappel anatomo-fonctionnel</strong> — <span class=\"kw-clinique\">les</span> glandes gastriques diffèrent selon le type de muqueuse :</p>\n      <table >\n        <thead><tr><th>Glandes</th><th>Cellules & sécrétions</th></tr></thead>\n        <tbody>\n          <tr><td>Fundiques</td><td><span class=\"kw-def\">Cellules pariétales</span> (HCl + facteur intrinsèque) ; <span class=\"kw-def\">cellules principales</span> (pepsinogène) ; <span class=\"kw-def\">cellules ECL</span> (histamine)</td></tr>\n          <tr><td>Antrales</td><td>Cellules <span class=\"kw-def\">mucosécrétantes</span> ; cellules endocrines <span class=\"kw-def\">à gastrine</span> (stimule l'HCl fundique et <span class=\"kw-clinique\">les</span> cellules ECL)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Causes de <span class=\"kw-clinique\">gastrite</span> :</strong></p>\n      <table >\n        <thead><tr><th>Cause</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">H. pylori</span></td><td>La <strong>1re cause</strong> ; <span class=\"kw-clinique\">gastrite</span> antrale</td></tr>\n          <tr><td><span class=\"kw-etio\">Auto-immune</span> (Biermer)</td><td><span class=\"kw-clinique\">Gastrite</span> <span class=\"kw-clinique\">fundique</span> ; sujet <span class=\"kw-chiffre\">> 50 ans</span>, prédominance féminine ; l'atrophie fundique entraîne une <span class=\"kw-bio\">carence en B12</span>, une <span class=\"kw-bio\">carence martiale</span> et une <span class=\"kw-bio\">hypergastrinémie réactionnelle</span> (risque de TNE à cellules ECL) ; séquence atrophie → métaplasie → dysplasie → <span class=\"kw-etio\">adénocarcinome</span></td></tr>\n          <tr><td>Lymphocytaire</td><td>Association à une <span class=\"kw-etio\">maladie cœliaque</span></td></tr>\n          <tr><td>À collagène</td><td>Rare ; <span class=\"kw-def\">dépôt de collagène sous-épithélial</span> ; à rapprocher de la colite collagène et de la <span class=\"kw-etio\">maladie cœliaque</span></td></tr>\n          <tr><td>Granulomateuse</td><td><span class=\"kw-etio\">Crohn, sarcoïdose, tuberculose, syphilis</span>, parasites, mycoses</td></tr>\n          <tr><td>À <span class=\"kw-bio\">éosinophiles</span></td><td><span class=\"kw-etio\">Allergie alimentaire, anisakiase</span></td></tr>\n          <tr><td>Associée à Crohn</td><td>Atteinte gastrique chez ≈ <span class=\"kw-chiffre\">30 %</span> des patients atteints de Crohn</td></tr>\n          <tr><td>Infectieuse</td><td><span class=\"kw-etio\">Virale</span> (<span class=\"kw-etio\">CMV, HSV</span>), phlegmoneuse (<span class=\"kw-etio\">bactérienne</span>) — surtout l'immunodéprimé</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 282 — <span class=\"kw-clinique\">MICI</span></em></p>","frequence":2},{"id":"272-19","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications et la place des biopsies pour le diagnostic, le traitement et le suivi","contenu":"<p>La <span class=\"kw-clinique\">gastrite</span> est un diagnostic <strong>histologique</strong> : <span class=\"kw-chiffre\">5 biopsies</span> (2 fundus, <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> an</span>tre, 1 angle de la petite courbure). Il n'existe pas de corrélation entre l'aspect endoscopique, l'<span class=\"kw-bio\">histologie</span> et <span class=\"kw-clinique\">les</span> symptômes.</p>\n      <p><strong>Indications des biopsies</strong> selon l'aspect endoscopique de la muqueuse :</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Objectif des biopsies</th></tr></thead>\n        <tbody>\n          <tr><td>Présence d'une <span class=\"kw-clinique\">lésion</span> endoscopique</td><td>Confirmer le diagnostic de <span class=\"kw-clinique\">gastrite</span> et en déterminer la cause</td></tr>\n          <tr><td>Absence de <span class=\"kw-clinique\">lésion</span> endoscopique</td><td>Rechercher une pathologie spécifique : <span class=\"kw-bio\">carence en B12 avec anémie macrocytaire</span> (recherche d'atrophie), ATCD familial de cancer gastrique, douleurs abdominales chroniques (recherche d'<span class=\"kw-etio\">H. pylori</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Traitement</strong> — une fois le diagnostic posé, il est <span class=\"kw-ttt\">ciblé sur la cause</span> identifiée : éradication d'HP, arrêt de l'<span class=\"kw-etio\">alcool</span>, traitement de l'<span class=\"kw-clinique\">hypertension</span> portale…</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-def\">Suivi</span> — </strong>une <span class=\"kw-alerte\">surveillance endoscopique à vie</span> avec biopsies est nécessaire pour : la <span class=\"kw-etio\">gastrite auto-immune de Biermer</span> (risque d'adénocarcinome et de tumeur neuro-endocrine) ; la <span class=\"kw-alerte\">gastrite à risque de dégénérescence</span> séquellaire d'une infection à HP (atrophie, métaplasie, dysplasie = <span class=\"kw-def\">lésions précancéreuses</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 303 — Tumeur estomac · 213 — Anémie</em></p>","frequence":3},{"id":"272-20","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la gastrite","contenu":"<p>Le traitement d'une <span class=\"kw-clinique\">gastrite</span> consiste à <strong>traiter la cause</strong> identifiée :</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Gastrite</span> à H. pylori</td><td><span class=\"kw-ttt\">Éradication d'H. pylori</span></td></tr>\n          <tr><td>Biermer (<span class=\"kw-etio\">auto-immune</span>)</td><td><span class=\"kw-alerte\">Pas de traitement curatif</span> ; <span class=\"kw-ttt\">supplémentation parentérale en vitamine B12</span> ± fer ; <span class=\"kw-def\">surveillance</span> endoscopique systématique tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 ans</span> chez le sujet < 70 ans en bon état général</td></tr>\n          <tr><td>Gastropathie chimique</td><td><span class=\"kw-ttt\">Arrêt de l'alcool</span> ou de la cause</td></tr>\n          <tr><td>Gastropathie d'<span class=\"kw-clinique\">HTP</span></td><td>Traitement de l'<span class=\"kw-ttt\">hypertension portale</span></td></tr>\n          <tr><td>Causes spécifiques</td><td>Traitement étiologique (<span class=\"kw-etio\">CMV</span>, <span class=\"kw-etio\">Crohn</span>…)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p>","frequence":0}],"astuces":[{"type":"tip","titre":"Mnémonique du syndrome ulcéreux","contenu":"Ulcère gastrique = douleur <strong>après</strong> le repas (post-prandial) comme si l'estomac se faisait gronder. Ulcère duodénal = douleur <strong>à jeun / nocturne</strong>, calmée par l'alimentation. Mnémotechnique : <em>« Gastro = Grincheux après manger ; Duodéno = Dormeur réveillé la nuit »</em>."},{"type":"danger","titre":"Toujours biopsier un ulcère gastrique","contenu":"Contrairement à l'ulcère duodénal (bénin), l'ulcère gastrique porte un risque de malignité. <strong>4 à 6 biopsies sur les bords + fond</strong> sont obligatoires. Un contrôle endoscopique à 6-8 sem est indispensable pour confirmer la cicatrisation et exclure un cancer masqué."},{"type":"warn","titre":"Test de guérison HP : les pièges de timing","contenu":"L'UBT (test respiratoire) et l'antigène fécal sont falsifiés par les IPP et les antibiotiques. Il faut impérativement attendre <strong>≥ 4 sem après la fin des antibiotiques</strong> et <strong>≥ 2 sem après l'arrêt de l'IPP</strong> pour un résultat fiable. Sinon : faux négatifs fréquents et échec thérapeutique méconnu."},{"type":"info","titre":"Classification de Forrest et conduite endoscopique","contenu":"Forrest Ia (saignement actif artériel) et Ib (veineux) = hémostase endoscopique <strong>impérative</strong>. Forrest IIa (vessel visible non saignant) et IIb (coagulum) = hémostase préventive recommandée. Forrest IIc (tache hematique) et III (fond propre) = pas d'hemostase endoscopique, IPP per os suffisant."},{"type":"tip","titre":"Gastrite autoimmune : ne pas oublier la B12","contenu":"La gastrite autoimmune détruit les cellules pariétales → absence de facteur intrinsèque et d'acide chlorhydrique. Résultat inévitable : <strong>anémie de Biermer</strong> (carence en B12) avec macrocytose et éventuellement neurologie (funis). Traitement : vitamine B12 per os à vie (1 mg/j) car dose massive permet absorption passive."}],"strategie":{"urgence":"<p><strong><span class=\"kw-clinique\">UGD</span> non compliqué</strong></p><p>diagnostic et traitement en ambulatoire</p><ul><li>pas d'<span class=\"kw-alerte\">urgence</span></li></ul><p><strong><span class=\"kw-clinique\">Hémorragie digestive haute</span></strong></p><p><span class=\"kw-ttt\">IPP IV</span> en continu sans retarder l'<span class=\"kw-imagerie\">EOGD</span> ; <span class=\"kw-imagerie\">endoscopie</span> diagnostique et thérapeutique dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">24 h</span></p><ul><li><span class=\"kw-alerte\">urgence vitale</span> (<span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">≈ 10 %</span>)</li></ul><p><strong>Perforation peritonisée</strong></p><p><span class=\"kw-imagerie\">TDM AP injectée</span> en 1ʳᵉ intention, <span class=\"kw-ci\">EOGD formellement contre-indiquée</span></p><ul><li><span class=\"kw-alerte\">urgence chirurgicale</span> après <strong>courte <span class=\"kw-alerte\">réanimation</span></strong></li></ul><p><strong>Contracture abdominale</strong></p><p>1er geste = <span class=\"kw-imagerie\">TDM AP injectée</span> (pneumopéritoine + réaction <span class=\"kw-etio\">inflammatoire</span> antro-pyloro-bulbaire)</p><p><strong>Sténose ulcéreuse</strong></p><ul><li>non urgent mais bilan <span class=\"kw-alerte\">hospitalisation</span> (alcalose métabolique, dénutrition) avant <span class=\"kw-ttt\">chirurgie</span></li></ul>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-clinique\">UGD</span> non compliqué (diagnostic à l'<span class=\"kw-imagerie\">EOGD</span>, traitement <span class=\"kw-ttt\">IPP</span> ± éradication HP, <span class=\"kw-def\">suivi</span> clinique).<br><strong><span class=\"kw-alerte\">Hospitalisation</span> conventionnelle :</strong> hémorragie digestive stabilisée (<span class=\"kw-def\">Forrest IIc-III</span>), sténose à bilanter, perforation-bouchée stable.<br><strong><span class=\"kw-alerte\">USI</span> / Réanimation :</strong> <span class=\"kw-alerte\">choc hémorragique</span>, instabilité hémodynamique persistante, transfusion massive, <span class=\"kw-clinique\">troubles de conscience</span>, saignement actif au scope.<br><strong><span class=\"kw-ttt\">Chirurgie</span> d'<span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-clinique\">péritonite</span> par perforation ; hémorragie <span class=\"kw-alerte\">réfractaire</span> à l'<span class=\"kw-ttt\">hémostase endoscopique</span> + <span class=\"kw-ttt\">embolisation artérielle</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Contracture abdominale</span> / <span class=\"kw-clinique\">défense</span>, douleur au TR (Douglas douloureux) — <span class=\"kw-clinique\">péritonite</span> par perforation</li><li><span class=\"kw-alerte\">Tympanisme + disparition de la matité préhépatique</span> — pneumopéritoine clinique (signe quasi-pathognomonique)</li><li><span class=\"kw-alerte\">Hématémèse</span>, <span class=\"kw-alerte\">méléna</span>, sang rouge au toucher rectal — hémorragie digestive extériorisée</li><li><span class=\"kw-clinique\">Tachycardie</span> <span class=\"kw-chiffre\">&gt; 100 bpm</span> (meilleur signe précoce de <span class=\"kw-alerte\">défaillance</span> HD) ; <span class=\"kw-alerte\">bradycardie</span> = gravité extrême ; <span class=\"kw-clinique\">hypotension</span> artérielle</li><li>Hypoperfusion : <span class=\"kw-clinique\">marbrures</span>, allongement du TRC, oligurie <span class=\"kw-chiffre\">&lt; 0,5 mL/kg/h</span>, <span class=\"kw-clinique\">troubles de la vigilance</span></li><li><span class=\"kw-clinique\">Vomissements post-prandiaux tardifs</span> + <span class=\"kw-bio\">alcalose métabolique hypochlorémique hypokaliémique</span> — sténose ulcéreuse</li><li><span class=\"kw-alerte\">Amaigrissement</span>, <span class=\"kw-clinique\">ganglion de Troisier</span> (<span class=\"kw-clinique\">adénopathie</span> sus-claviculaire G) — cancer associé sur ulcère gastrique</li><li><span class=\"kw-clinique\">Ulcère duodénal post-bulbaire</span> (très rare) — évoquer <span class=\"kw-etio\">Zollinger-Ellison</span> ou <span class=\"kw-etio\">MICI</span> (Crohn, <span class=\"kw-clinique\">vascularite</span>)</li><li><span class=\"kw-def\">Terrain</span> à risque de forme compliquée : <span class=\"kw-chiffre\">âge &gt; 65 ans</span>, ATCD d'<span class=\"kw-clinique\">UGD</span> compliqué, <span class=\"kw-ttt\">AINS</span> + <span class=\"kw-etio\">H. pylori</span>, <span class=\"kw-ttt\">anticoagulants</span></li></ul>","principes":"<p>Couvrir l'<span class=\"kw-clinique\">UGD</span> par <span class=\"kw-ttt\">IPP</span> (cicatrisation requiert <span class=\"kw-chiffre\">pH &gt; 3</span>), <span class=\"kw-ttt\">éradiquer H. pylori</span> (prévention de la récidive ≈ constante si non éradiqué), traiter le facteur favorisant (arrêt <span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">aspirine</span> si possible), contrôler la <strong>cicatrisation</strong> (<span class=\"kw-imagerie\">EOGD</span> systématique pour l'UG, biopsies des berges).</p><p><strong>Ulcère duodénal non compliqué</strong></p><ul><li><span class=\"kw-ttt\">IPP simple dose</span> pendant <span class=\"kw-chiffre\">4 semaines</span></li><li>pas de contrôle endoscopique si patient asymptomatique</li></ul><p><strong>Ulcère gastrique non compliqué</strong></p><ul><li><span class=\"kw-ttt\">IPP simple dose</span> pendant <span class=\"kw-chiffre\">4 à 8 semaines</span> + <span class=\"kw-imagerie\">contrôle endoscopique systématique</span> de la cicatrisation avec biopsies (zone cicatricielle + recherche HP)</li></ul><p><strong>Éradication <span class=\"kw-clinique\">H. pylori</span> <span class=\"q\">— quadrithérapie bismuthée</span></strong></p><ul><li><span class=\"kw-ttt\">métronidazole + tétracycline + oméprazole double dose + sous-citrate de bismuth</span> sur <span class=\"kw-chiffre\">10 jours</span> — si <span class=\"kw-ci\">allergie aux β-lactamines</span>, sensibilités non connues, résistance à <span class=\"kw-ttt\">clarithromycine</span>/<span class=\"kw-ttt\">lévofloxacine</span></li></ul><p><strong>Éradication <span class=\"kw-clinique\">H. pylori</span> <span class=\"q\">— quadrithérapie concomitante</span></strong></p><ul><li><span class=\"kw-ttt\">métronidazole + amoxicilline + clarithromycine + IPP double dose</span> sur <span class=\"kw-chiffre\">14 jours</span> — sensibilités non connues sans <span class=\"kw-ci\">allergie</span></li></ul><p><strong>Éradication <span class=\"kw-clinique\">H. pylori</span> <span class=\"q\">— <span class=\"kw-ttt\">trithérapie</span> ciblée</span></strong></p><ul><li><span class=\"kw-ttt\">amoxicilline + IPP double dose + clarithromycine</span> (ou <span class=\"kw-ttt\">lévofloxacine</span> si résistance) sur <span class=\"kw-chiffre\">10 jours</span> — sensibilité connue, pas d'<span class=\"kw-ci\">allergie</span></li></ul><p><strong><span class=\"kw-clinique\">UGD</span> induit <span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">aspirine</span></strong></p><ul><li>traitement standard + <span class=\"kw-ttt\">IPP de maintien</span> si <span class=\"kw-ttt\">AINS</span> indispensable</li><li><span class=\"kw-ttt\">IPP préventif</span> si <span class=\"kw-chiffre\">âge &gt; 65 ans</span>, ATCD <span class=\"kw-clinique\">UGD</span>, <span class=\"kw-ttt\">anti-thrombotique</span> ou <span class=\"kw-ttt\">corticoïdes</span> associés</li></ul><p><strong>Hémorragie ulcéreuse <span class=\"q\">— <span class=\"kw-alerte\">réanimation</span></span></strong></p><ul><li>2 VVP, oxygénation, scope, bilan (<span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">hémostase</span>, <span class=\"kw-bio\">2 groupages + RAI</span>, <span class=\"kw-bio\">créatinine</span>), antagonisation des <span class=\"kw-ttt\">anticoagulants</span>, <span class=\"kw-ttt\">IPP IV en continu</span> sans retarder l'<span class=\"kw-imagerie\">EOGD</span></li></ul><p><strong>Hémorragie Forrest Ia-IIb <span class=\"q\">(signes endoscopiques de gravité)</span></strong></p><ul><li><span class=\"kw-ttt\">hémostase endoscopique</span> (thermocoagulation + clips ± sérum adrénaliné) + <span class=\"kw-ttt\">IPP fortes doses en IV continu pendant 48-72 h</span>, puis relais per os à pleine dose</li></ul><p><strong>Hémorragie Forrest IIc-III</strong></p><ul><li><span class=\"kw-ttt\">IPP pleine dose per os</span> d'emblée + <span class=\"kw-def\">surveillance</span></li><li>pas d'hémostase endoscopique nécessaire</li></ul><p><strong>Hémorragie réfractaire</strong></p><ul><li><span class=\"kw-ttt\">embolisation artérielle</span> (artère gastro-duodénale ou gastrique gauche selon localisation), puis <span class=\"kw-ttt\">chirurgie</span> d'hémostase si échec</li></ul><p><strong>Perforation peritonisée</strong></p><ul><li><span class=\"kw-ttt\">chirurgie</span> d'<span class=\"kw-alerte\">urgence</span> (suture-épiploplastie ou résection) + <span class=\"kw-ttt\">antibiothérapie probabiliste IV</span> couvrant flore digestive</li><li><span class=\"kw-ci\">EOGD contre-indiquée</span></li></ul><p><strong>Perforation-bouchée stable <span class=\"q\">(méthode de Taylor)</span></strong></p><ul><li>SNG en aspiration + <span class=\"kw-ttt\">IPP IV</span> + <span class=\"kw-ttt\">antibiotiques IV</span> + jeûne strict, sous <span class=\"kw-def\">surveillance</span> clinique rapprochée — uniquement en l'absence de <span class=\"kw-alerte\">signe de gravité</span></li></ul><p><strong><span class=\"kw-alerte\">Choc</span> <span class=\"kw-etio\">hémorragique</span> <span class=\"q\">— objectifs</span></strong></p><ul><li>remplissage par cristalloïdes ± <span class=\"kw-ttt\">noradrénaline</span> si PAS &lt;<span class=\"kw-chiffre\"> 80 mmHg</span> malgré<span class=\"kw-chiffre\"> 1-1,5 L</span> ± transfusion</li><li>cibles <span class=\"kw-chiffre\">FC &lt; 100 bpm</span>, <span class=\"kw-chiffre\">PAS &gt; 100 mmHg</span> (ou PAM <span class=\"kw-chiffre\">≥ 65</span>), diurèse &gt;<span class=\"kw-chiffre\"> 0,5 mL</span>/kg/h, <span class=\"kw-chiffre\">Hb 7-9 g/dL</span> (7-8 si varices, &gt; 9 si <span class=\"kw-def\">comorbidités</span> cardiovasculaires)</li></ul><p><strong><span class=\"kw-clinique\">Gastrite</span> <span class=\"q\">— principe</span></strong></p><ul><li>traitement <span class=\"kw-ttt\">étiologique ciblé</span> (éradication HP, arrêt <span class=\"kw-etio\">alcool</span>, supplémentation <span class=\"kw-ttt\">B12 parentérale</span> si Biermer, traitement de l'<span class=\"kw-clinique\">HTP</span> pour gastropathie congestive)</li></ul>","suivi":"<p><strong>Contrôle d'éradication <span class=\"kw-clinique\">H. pylori</span> — systématique</strong> (≈ <span class=\"kw-chiffre\">10 %</span> d'échec en 1ʳᵉ ligne) : <span class=\"kw-chiffre\">4 semaines après la fin des antibiotiques</span> et <span class=\"kw-chiffre\">2 semaines après l'arrêt des IPP</span>.<br><strong>UD ou <span class=\"kw-def\">dépistage</span> :</strong> <span class=\"kw-bio\">test respiratoire à l'urée marquée C13</span> (seul test remboursé pour le contrôle).<br><strong>UG :</strong> <span class=\"kw-imagerie\">contrôle endoscopique impératif</span> avec biopsies de la zone cicatricielle (recherche d'<span class=\"kw-etio\">adénocarcinome</span> + contrôle HP).<br><strong>Échec d'éradication :</strong> switch de schéma sans <span class=\"kw-imagerie\">EOGD</span> puis nouveau contrôle ; en cas de nouvel échec, <span class=\"kw-imagerie\">EOGD + biopsies avec étude de la sensibilité aux antibiotiques</span>.<br><strong><span class=\"kw-def\">Surveillance</span> endoscopique à vie :</strong> <span class=\"kw-etio\">gastrite auto-immune de Biermer</span> (risque d'adénocarcinome et de TNE à cellules ECL) ; <span class=\"kw-alerte\">lésions précancéreuses séquellaires d'HP</span> (atrophie sévère, métaplasie intestinale, dysplasie).<br><strong>Pas d'<span class=\"kw-ttt\">IPP</span> au long cours</strong> après éradication HP si UD non compliqué ; <span class=\"kw-ttt\">IPP curatif 6 semaines</span> si UG ou UD compliqué, ou douleurs persistantes, ou poursuite d'<span class=\"kw-ttt\">AINS</span> / antithrombotiques.</p>"},"liensGlobaux":[{"href":"https://facmed-univ-oran.dz/ressources/fichiers_produits/fichier_produit_2037.pdf","label":"Fichier produit 2037"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Douleur épigastrique évocatrice d'UGD — Premier tri clinique","detail":"<h4>CAT — suspicion d'<span class=\"kw-clinique\">UGD</span> — Orientation initiale : perforation / hémorragie / forme non compliquée</h4>","branches":[{"to":"q-tdm-pneumo","label":"Contracture / défense abdominale","color":"red"},{"to":"q-forrest","label":"Hématémèse / méléna / instabilité HD","color":"red"},{"to":"q-eogd","label":"Ni contracture ni saignement","color":"green"}]},{"id":"q-tdm-pneumo","kind":"decision","label":"TDM abdomino-pelvienne injectée — pneumopéritoine ? — Examen de 1ʳᵉ intention · EOGD contre-indiquée","branches":[{"to":"q-stabilite-perfo","label":"Oui — péritonite confirmée","color":"red"},{"to":"t-reeval","label":"Non — pas de pneumopéritoine","color":"blue"}]},{"id":"q-stabilite-perfo","kind":"decision","label":"Stabilité hémodynamique + absence de sepsis ? — Recherche d'une perforation-bouchée stable","branches":[{"to":"t-chirurgie","label":"Non — instable / sepsis","color":"red"},{"to":"t-taylor","label":"Oui — perforation-bouchée stable","color":"amber"}]},{"id":"t-chirurgie","kind":"terminal","label":"Chirurgie en urgence","color":"red","detail":"<h4>Délai</h4><ul><li>Intervention chirurgicale en <span class=\"kw-alerte\">urgence</span>, précédée d'une courte <span class=\"kw-alerte\">réanimation</span>.</li></ul><h4>Conduite</h4><ul><li>Suture-épiploplastie (ulcère simple) ou résection (ulcère gastrique suspect de néoplasie)</li><li><span class=\"kw-ttt\">Antibiothérapie probabiliste IV</span> couvrant la flore digestive (entérobactéries, <span class=\"kw-etio\">anaérobies</span>, entérocoques)</li><li>Toilette péritonéale per-opératoire</li><li><span class=\"kw-ttt\">IPP IV</span> en post-op</li></ul><h4>Piège</h4><ul><li><span class=\"kw-ci\">EOGD formellement contre-indiquée</span> en cas de perforation (risque d'aggravation par insufflation).</li></ul>"},{"id":"t-taylor","kind":"terminal","label":"Méthode de Taylor (traitement médical)","color":"amber","detail":"<h4>Indication</h4><ul><li>Perforation au <span class=\"kw-def\">contact</span> du pancréas (perforation-bouchée), régression de la douleur initiale, <span class=\"kw-alerte\">pas de pneumopéritoine</span> (possible rétro-pneumopéritoine), en l'absence de <span class=\"kw-alerte\">signe de gravité</span>.</li></ul><h4>Conduite</h4><ul><li>SNG en aspiration continue</li><li><span class=\"kw-ttt\">IPP IV</span></li><li><span class=\"kw-ttt\">Antibiotiques IV</span></li><li>Jeûne strict, repos digestif</li><li><span class=\"kw-def\">Surveillance</span> clinique rapprochée (douleur, <span class=\"kw-clinique\">fièvre</span>, hémodynamique)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> de sauvetage si apparition de signes péritonéaux, <span class=\"kw-alerte\">sepsis</span> ou <span class=\"kw-alerte\">choc</span>.</li></ul>"},{"id":"t-reeval","kind":"terminal","label":"Réévaluation diagnostique","color":"blue","detail":"<h4>Diagnostics différentiels</h4><ul><li><span class=\"kw-clinique\">Pancréatite aiguë</span> (lipasémie, <span class=\"kw-imagerie\">scanner</span> pancréatique)</li><li>Ischémie mésentérique (<span class=\"kw-imagerie\">scanner</span> injecté, <span class=\"kw-bio\">lactates</span>)</li><li><span class=\"kw-clinique\">Cholécystite</span>, angiocholite</li><li><span class=\"kw-clinique\">Infarctus</span> du myocarde inférieur (<span class=\"kw-imagerie\">ECG</span>, <span class=\"kw-bio\">troponine</span>)</li><li>Colique néphrétique compliquée</li></ul><h4>Conduite</h4><ul><li>Compléter le bilan <span class=\"kw-ttt\">biologique</span> (<span class=\"kw-bio\">lipase</span>, <span class=\"kw-bio\">troponine</span>, <span class=\"kw-bio\">lactates</span>, BHC) et imageries ciblées. Pas d'<span class=\"kw-imagerie\">EOGD</span> tant que la perforation n'est pas formellement éliminée.</li></ul>"},{"id":"q-forrest","kind":"decision","label":"EOGD en urgence — classification de Forrest ? — Après réanimation hémodynamique + IPP IV continu, sans retarder l'endoscopie","branches":[{"to":"t-hemostase","label":"Ia–IIb · signes endoscopiques de gravité","color":"red"},{"to":"t-ipp-po","label":"IIc–III · pas de signes de gravité","color":"amber"}]},{"id":"t-hemostase","kind":"terminal","label":"Hémostase endoscopique + IPP IV continu 48-72 h","color":"red","detail":"<h4>Stades concernés</h4><ul><li>Ia : hémorragie en jet (artérielle active)</li><li>Ib : suintement diffus</li><li>IIa : vaisseau visible non <span class=\"kw-etio\">hémorragique</span></li><li>IIb : caillot adhérent</li></ul><h4>Traitement endoscopique</h4><ul><li>Thermocoagulation + clips ± injection de sérum adrénaliné (double méthode recommandée)</li><li><span class=\"kw-ttt\">IPP fortes doses en IV continu pendant 48-72 h</span></li><li>Puis relais per os à pleine dose</li></ul><h4>Échec endoscopique</h4><ul><li><span class=\"kw-ttt\">Embolisation artérielle</span> en 2ᵉ intention (artère gastro-duodénale si UD postérieur, artère gastrique gauche si UG petite courbure), puis <span class=\"kw-ttt\">chirurgie</span> d'hémostase en 3ᵉ intention.</li></ul><h4>Recherche HP</h4><ul><li>En contexte <span class=\"kw-etio\">hémorragique</span>, biopsies non réalisables → <span class=\"kw-bio\">sérologie HP</span> (annale EDN).</li></ul>"},{"id":"t-ipp-po","kind":"terminal","label":"IPP pleine dose per os + surveillance","color":"amber","detail":"<h4>Stades concernés</h4><ul><li>IIc : taches p<span class=\"kw-chiffre\">igm</span>entées (hématine)</li><li>III : cratère à fond propre</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">IPP pleine dose per os</span> d'emblée, pas d'IV continu nécessaire</li><li>Pas d'hémostase endoscopique (risque <span class=\"kw-etio\">hémorragique</span> faible)</li><li><span class=\"kw-alerte\">Hospitalisation</span> conventionnelle, scope, <span class=\"kw-def\">surveillance</span> clinique et <span class=\"kw-ttt\">biologique</span></li></ul><h4>À distance</h4><ul><li>Recherche d'<span class=\"kw-etio\">H. pylori</span> dès que possible (biopsies), <span class=\"kw-ttt\">éradication</span> si positive ; arrêt des <span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">aspirine</span> si non indispensables.</li></ul>"},{"id":"q-eogd","kind":"decision","label":"Indications d'EOGD ? — Âge > 50 ans · signes d'alarme (dysphagie, amaigrissement, hémorragie, anémie) · échec du traitement symptomatique","branches":[{"to":"t-eogd-diag","label":"Oui — au moins 1 critère","color":"blue"},{"to":"t-ipp-test","label":"Non — patient jeune sans red flag","color":"green"}]},{"id":"t-eogd-diag","kind":"terminal","label":"EOGD diagnostique avec biopsies HP","color":"blue","detail":"<h4>Modalités</h4><ul><li>Anesthésie locale pharyngée (AG non nécessaire)</li><li>Description de l'ulcère : perte de substance creusante, fond pseudo-membraneux blanchâtre, bords réguliers</li></ul><h4>Biopsies</h4><ul><li><span class=\"kw-alerte\">Recherche HP systématique</span> : biopsies gastriques antrales ET fundiques (<span class=\"kw-alerte\">jamais duodénales</span>)</li><li>Si UG : <span class=\"kw-chiffre\">6 à 12 biopsies des berges</span> en plus, à la recherche d'<span class=\"kw-etio\">adénocarcinome</span> ou de lymphome</li><li>Si UD : pas de <span class=\"kw-ttt\">biopsie</span> de la <span class=\"kw-clinique\">lésion</span> duodénale</li></ul><h4>Suite</h4><ul><li>UG : <span class=\"kw-ttt\">IPP simple dose 4-8 sem</span> + <span class=\"kw-imagerie\">contrôle endoscopique systématique</span> avec biopsies de la zone cicatricielle</li><li>UD : <span class=\"kw-ttt\">IPP simple dose 4 sem</span> ; pas de contrôle endoscopique si asymptomatique</li><li>Si HP+ : éradication par <span class=\"kw-ttt\">quadrithérapie</span> (bismuthée si <span class=\"kw-ci\">allergie</span> β-lact, concomitante sinon), contrôle d'éradication systématique</li></ul><h4>Piège</h4><ul><li>Ulcère duodénal post-bulbaire (très rare) → évoquer <span class=\"kw-etio\">Zollinger-Ellison</span> ou <span class=\"kw-etio\">MICI</span>.</li></ul>"},{"id":"t-ipp-test","kind":"terminal","label":"IPP test 4 semaines + réévaluation","color":"green","detail":"<h4>Indication</h4><ul><li>Patient <span class=\"kw-chiffre\">&lt; 50 ans</span>, sans signe d'alarme, douleur ép<span class=\"kw-chiffre\">iga</span>strique évocatrice de <span class=\"kw-clinique\">syndrome ulcéreux</span> ou de <span class=\"kw-clinique\">RGO</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">IPP simple dose pendant 4 semaines</span></li><li>Prise à jeun, le matin,<span class=\"kw-chiffre\"> 15-30 min</span> avant le repas</li><li><span class=\"kw-ttt\">Règles hygiéno-diététiques</span> (arrêt <span class=\"kw-ttt\">AINS</span> si possible, arrêt tabac)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Réévaluation</span> clinique à<span class=\"kw-chiffre\"> 4 semaines</span> : si efficacité → arrêt ; si inefficacité ou récidive → <span class=\"kw-imagerie\">EOGD diagnostique</span> avec biopsies HP.</li></ul>"}]},"cards":[{"i":"17b213acbbc2","n":272,"o":"272-1","u":"Définition","t":"Connaître les définitions d'un ulcère gastrique ou duodénal","q":"Quelles sont les localisations préférentielles de l'ulcère duodénal ?","a":"<p>L'ulcère duodénal se localise préférentiellement <strong>en plein bulbe</strong> ou <strong>à la pointe du bulbe</strong> (D1).</p>"},{"i":"3a0bd89b775e","n":272,"o":"272-1","u":"Définition","t":"Connaître les définitions d'un ulcère gastrique ou duodénal","q":"Quelles sont les localisations préférentielles de l'ulcère gastrique ?","a":"<p>L'ulcère gastrique se localise préférentiellement au niveau de l'<strong>antre</strong> et de la <strong>petite courbure</strong>.</p>"},{"i":"5b8254608440","n":272,"o":"272-1","u":"Définition","t":"Connaître les définitions d'un ulcère gastrique ou duodénal","q":"Quelle est la définition physiopathologique de l'ulcère gastroduodénal ?","a":"<p>L'ulcère gastroduodénal (UGD) résulte d'un <strong>déséquilibre</strong> entre l'<strong>agression chlorhydropeptique</strong> et les <strong>mécanismes de défense de la muqueuse</strong>, en un point précis de la paroi.</p>"},{"i":"68608d3ebaf3","n":272,"o":"272-1","u":"Définition","t":"Connaître les définitions d'un ulcère gastrique ou duodénal","q":"Comment différencier une érosion, une ulcération et un ulcère gastroduodénal selon la profondeur de l'atteinte ?","a":"<ul><li><strong>Érosion</strong> : limitée à la <strong>muqueuse</strong>.</li><li><strong>Ulcération</strong> : limitée à la <strong>sous-muqueuse</strong>.</li><li><strong>Ulcère</strong> : atteint la <strong>musculeuse</strong>.</li></ul>"},{"i":"d6fa793486a6","n":272,"o":"272-1","u":"Définition","t":"Connaître les définitions d'un ulcère gastrique ou duodénal","q":"Qu'est-ce qui caractérise histologiquement un ulcère chronique par rapport à un ulcère aigu ?","a":"<p>L'ulcère chronique se distingue de l'ulcère aigu par l'existence d'un <strong>socle scléro-inflammatoire</strong> dans la musculeuse, contenant des hyperplasies nerveuses et des lésions d'endartérite.</p>"},{"i":"f946e5862d10","n":272,"o":"272-1","u":"Définition","t":"Connaître les définitions d'un ulcère gastrique ou duodénal","q":"Quelles sont les trois lignes de défense de la barrière muqueuse gastroduodénale ?","a":"<ul><li><strong>Pré-épithéliale</strong> : mucus, phospholipides et bicarbonates.</li><li><strong>Épithéliale</strong> : cellules de surface assurant le renouvellement cellulaire.</li><li><strong>Sous-épithéliale</strong> : flux sanguin muqueux (vascularisation).</li></ul>"},{"i":"65049b03bcfa","n":272,"o":"272-10","u":"Identifier une urgence","t":"Connaître les principales complications de l'ulcère","q":"Quelles sont les caractéristiques de la sténose, une complication de l'ulcère gastroduodénal ?","a":"<p>La sténose est une complication <strong>exceptionnelle</strong> de l'ulcère gastroduodénal. Elle complique les <strong>ulcères bulbaires et pré-pyloriques</strong>. Cliniquement, elle se manifeste par des <strong>vomissements post-prandiaux tardifs</strong>. Elle expose à un risque d'<strong>alcalose métabolique hypochlorémique hypokaliémique</strong>.</p>"},{"i":"a478b9faac23","n":272,"o":"272-10","u":"Identifier une urgence","t":"Connaître les principales complications de l'ulcère","q":"Quelle est la complication la plus fréquente de l'ulcère gastroduodénal et quelles sont ses caractéristiques ?","a":"<p>La complication la plus fréquente de l'ulcère gastroduodénal est l'<strong>hémorragie digestive</strong>. Elle est parfois inaugurale, représente <strong>30 à 40 % des hémorragies digestives hautes</strong>, et s'accompagne d'une mortalité d'environ <strong>10 %</strong>.</p>"},{"i":"e0c3660ebbaf","n":272,"o":"272-10","u":"Identifier une urgence","t":"Connaître les principales complications de l'ulcère","q":"Un ulcère gastroduodénal peut-il dégénérer en cancer ?","a":"<p>Oui, mais la <strong>dégénérescence</strong> ne concerne que l'<strong>ulcère gastrique</strong>. L'ulcère duodénal ne dégénère jamais.</p>"},{"i":"efb8c2b1a843","n":272,"o":"272-10","u":"Identifier une urgence","t":"Connaître les principales complications de l'ulcère","q":"Quelles sont les caractéristiques de la perforation, une complication de l'ulcère gastroduodénal ?","a":"<p>La perforation est une complication <strong>moins fréquente</strong> que l'hémorragie. Sa survenue est favorisée par la prise d'<strong>AINS</strong>.</p>"},{"i":"226d06261071","n":272,"o":"272-11","u":"Identifier une urgence","t":"Connaître la stratégie à adopter devant une hématémèse","q":"Quels sont les pièges à éviter lors de l'évaluation initiale de la gravité d'une hématémèse ?","a":"<ul><li>La quantité de <strong>sang extériorisé</strong> est un <strong>mauvais critère de gravité</strong>.</li><li>Le taux d'<strong>hémoglobine/hématocrite</strong> peut <strong>sous-estimer</strong> initialement l'hémorragie.</li><li>Le sujet jeune peut <strong>compenser longtemps</strong> par une tachycardie.</li></ul>"},{"i":"40e2580548ba","n":272,"o":"272-11","u":"Identifier une urgence","t":"Connaître la stratégie à adopter devant une hématémèse","q":"Quelle est l'orientation du patient et le rôle de l'endoscopie digestive haute (EOGD) en cas d'hématémèse ?","a":"<ul><li><strong>Orientation</strong> : le patient stable est orienté en service conventionnel ; le patient instable, présentant un saignement actif ou un état de choc, est orienté en <strong>USI/réanimation</strong>.</li><li><strong>EOGD</strong> : elle est <strong>diagnostique, pronostique</strong> (classification de Forrest) et <strong>thérapeutique</strong>. Elle doit être réalisée <strong>rapidement</strong>.</li><li>L'hémostase endoscopique (thermocoagulation/clips ± sérum adrénaliné) est indiquée pour les stades <strong>Forrest Ia à IIb</strong>.</li><li>En cas d'échec de l'hémostase endoscopique, une <strong>embolisation</strong> ou une <strong>chirurgie</strong> peut être envisagée.</li></ul>"},{"i":"745938002271","n":272,"o":"272-11","u":"Identifier une urgence","t":"Connaître la stratégie à adopter devant une hématémèse","q":"Quelle est la prise en charge spécifique du choc hémorragique secondaire à une hématémèse ?","a":"<p>La prise en charge du choc hémorragique repose sur :</p><ul><li>Le <strong>remplissage</strong> par <strong>cristalloïdes</strong>.</li><li>L'administration de <strong>noradrénaline</strong> si la PAM (Pression Artérielle Moyenne) est &lt; 65 mmHg après remplissage.</li><li>Les <strong>transfusions sanguines</strong> en cas d'échec du remplissage ou d'Hb ciblée entre <strong>7 et 9 g/dL</strong> (7-8 si varices, &gt; 9 si comorbidités cardiovasculaires). Les objectifs sont une FC &lt; 100 bpm, une PAS &gt; 100 mmHg ou PAM ≥ 65 mmHg, une diurèse &gt; 0,5 mL/kg/h.</li></ul>"},{"i":"a1a3e20067e9","n":272,"o":"272-11","u":"Identifier une urgence","t":"Connaître la stratégie à adopter devant une hématémèse","q":"Quels sont les signes d'évaluation de la gravité d'une hématémèse ?","a":"<p>Les signes d'évaluation de la gravité d'une hématémèse sont :</p><ul><li>La <strong>tachycardie</strong> (FC &gt; 100 bpm), meilleur signe précoce de défaillance hémodynamique.</li><li>L'<strong>hypotension artérielle</strong>.</li><li>La <strong>bradycardie</strong>, signe de gravité extrême.</li><li>Les signes d'hypoperfusion : <strong>marbrures</strong>, allongement du <strong>TRC</strong> (temps de recoloration cutanée), <strong>oligurie</strong>, troubles de conscience.</li></ul>"},{"i":"b6c0d085cdf6","n":272,"o":"272-11","u":"Identifier une urgence","t":"Connaître la stratégie à adopter devant une hématémèse","q":"Quelle est la stratégie de traitement par IPP après une hémorragie digestive haute en fonction des stades de Forrest ?","a":"<ul><li>Pour les stades <strong>Forrest Ia à IIb</strong> (signes endoscopiques de gravité) : <strong>IPP à fortes doses en IV continu</strong> pendant <strong>48 à 72 heures</strong>, puis relais per os à pleine dose.</li><li>Pour les stades <strong>Forrest IIc à III</strong> (pas de signe endoscopique de gravité) : <strong>relais précoce par IPP pleine dose per os</strong>.</li></ul>"},{"i":"d30f37f070ab","n":272,"o":"272-11","u":"Identifier une urgence","t":"Connaître la stratégie à adopter devant une hématémèse","q":"Quelles sont les premières mesures à adopter devant une hématémèse, avant l'endoscopie ?","a":"<p>Les premières mesures sont :</p><ul><li>Mettre en place <strong>deux voies veineuses périphériques</strong>.</li><li>Assurer une <strong>oxygénation</strong>.</li><li>Mettre en place un <strong>monitorage</strong> (scope) : SaO2, pouls, pression artérielle (PA), diurèse.</li><li>Réaliser un <strong>bilan biologique</strong> : NFS, ionogramme, créatinine, calcémie, hémostase, <strong>deux groupages + RAI</strong> (Recherche d'Agglutinines Irrégulières) et éventuellement des gaz du sang.</li><li><strong>Arrêter</strong> et <strong>antagoniser</strong> les anticoagulants si le patient en prend.</li><li>Commencer les <strong>IPP en IVSE</strong> dès l'admission, sans retarder l'endoscopie.</li></ul>"},{"i":"4ed8e78839e7","n":272,"o":"272-12","u":"Identifier une urgence","t":"Connaître les mesures à mettre en œuvre dans les formes perforées","q":"Quel est l'examen paraclinique de première intention en cas de suspicion de perforation d'un ulcère gastroduodénal en péritoine libre ?","a":"<p>L'examen de première intention en cas de suspicion de perforation d'un ulcère gastroduodénal en péritoine libre est une <strong>TDM abdomino-pelvienne injectée</strong>.</p><p>Cet examen objective un <strong>pneumopéritoine</strong> et une réaction inflammatoire antro-pyloro-bulbaire. L'<strong>endoscopie est formellement contre-indiquée</strong>.</p>"},{"i":"89988820ea8a","n":272,"o":"272-12","u":"Identifier une urgence","t":"Connaître les mesures à mettre en œuvre dans les formes perforées","q":"Quels sont les signes cliniques évoquant une perforation d'un ulcère gastroduodénal en péritoine libre ?","a":"<p>La perforation d'un ulcère gastroduodénal en péritoine libre se manifeste par :</p><ul><li>Une douleur épigastrique en <strong>coup de poignard</strong>, d'apparition <strong>brutale</strong>, diffusant rapidement à l'ensemble de l'abdomen.</li><li>Une <strong>contracture abdominale</strong> (« ventre de bois »).</li><li>Un Douglas douloureux au toucher rectal.</li><li>Des signes de choc.</li><li>Un tympanisme à la percussion et une <strong>disparition de la matité préhépatique</strong> (signe de pneumopéritoine, quasi-pathognomonique).</li><li>Initialement, l'absence de fièvre et d'hyperleucocytose (péritonite chimique).</li></ul>"},{"i":"901cddd97878","n":272,"o":"272-12","u":"Identifier une urgence","t":"Connaître les mesures à mettre en œuvre dans les formes perforées","q":"Comment différencier une perforation en péritoine libre d'un ulcère gastroduodénal et un ulcère perforé-bouché ?","a":"<p>La perforation en péritoine libre se caractérise par :</p><ul><li>Une douleur initiale en <strong>coup de poignard</strong>.</li><li>Un <strong>pneumopéritoine</strong> (disparition de la matité préhépatique à l'examen clinique et air libre sous-diaphragmatique à la TDM).</li></ul><p>L'ulcère perforé-bouché (perforation au contact du pancréas) se distingue par :</p><ul><li>Une <strong>régression de la douleur initiale</strong>.</li><li>L'absence de pneumopéritoine (un rétro-pneumopéritoine est possible).</li></ul>"},{"i":"9da9dacf25d4","n":272,"o":"272-12","u":"Identifier une urgence","t":"Connaître les mesures à mettre en œuvre dans les formes perforées","q":"Quelle est la prise en charge spécifique d'un ulcère perforé-bouché stable, sans signe de gravité ?","a":"<p>En l'absence de signes de gravité, un ulcère perforé-bouché peut être géré selon la <strong>méthode de Taylor</strong>. Cette méthode consiste en :</p><ul><li>La pose d'une <strong>sonde naso-gastrique en aspiration</strong>.</li><li>L'administration d'<strong>inhibiteurs de la pompe à protons (IPP)</strong>.</li><li>Une <strong>antibiothérapie</strong> adaptée.</li></ul>"},{"i":"eccc65fa8665","n":272,"o":"272-12","u":"Identifier une urgence","t":"Connaître les mesures à mettre en œuvre dans les formes perforées","q":"Quelle est la prise en charge thérapeutique initiale d'une perforation d'ulcère gastroduodénal en péritoine libre ?","a":"<p>La perforation d'ulcère gastroduodénal en péritoine libre est une <strong>urgence chirurgicale</strong>. Elle impose une prise en charge de péritonite secondaire incluant, en plus de la chirurgie, une <strong>antibiothérapie probabiliste</strong>.</p>"},{"i":"154720927caa","n":272,"o":"272-15","u":"Prise en charge","t":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","q":"Quelle est la stratégie en cas d'échec de la première ligne de traitement d'éradication d'<i>Helicobacter pylori</i> ?","a":"<p>En cas d'échec de la première ligne de traitement d'éradication d'<i>H. pylori</i>, il faut :</p><ul><li><strong>Switcher de schéma thérapeutique</strong> sans réaliser d'EOGD (Endo-Oeso-Gastro-Duodénoscopie).</li><li>Effectuer un <strong>nouveau contrôle d'éradication</strong>.</li><li>En cas de second échec, réaliser une <strong>EOGD avec biopsies</strong> pour une étude de la sensibilité aux antibiotiques.</li></ul>"},{"i":"4f57b31ce06d","n":272,"o":"272-15","u":"Prise en charge","t":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","q":"Comment traite-t-on un ulcère gastrique non compliqué ?","a":"<p>Un ulcère gastrique non compliqué se traite par un <strong>inhibiteur de la pompe à protons (IPP) simple dose</strong> pendant <strong>4 à 8 semaines</strong>. Ce traitement doit impérativement être suivi d'un <strong>contrôle endoscopique</strong> de la cicatrisation avec biopsies.</p>"},{"i":"531a847d71c0","n":272,"o":"272-15","u":"Prise en charge","t":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","q":"Comment gère-t-on un ulcère gastroduodénal associé à <i>Helicobacter pylori</i> (HP) ?","a":"<p>La prise en charge d'un UGD associé à <i>H. pylori</i> se fait en trois temps :</p><ul><li><strong>IPP simple dose</strong> dès le diagnostic, en attente du résultat de la recherche d'HP.</li><li>Traitement d'éradication d'HP : <strong>IPP double dose + antibiotiques pendant 10 à 14 jours</strong>.</li><li>Après éradication : pas d'IPP au long cours si UD non compliqué ; <strong>IPP curatif 6 semaines</strong> si UG ou UD compliqué, poursuite d'AINS/anti-thrombotiques ou douleurs épigastriques persistantes, puis IPP préventif si poursuite d'AINS/aspirine.</li></ul>"},{"i":"60b29ba0de21","n":272,"o":"272-15","u":"Prise en charge","t":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","q":"Comment doit être réalisé le contrôle de l'éradication d'<i>Helicobacter pylori</i> après traitement ?","a":"<p>Le contrôle d'éradication est <strong>systématique</strong>, réalisé <strong>4 semaines après la fin des antibiotiques et 2 semaines après l'arrêt des IPP</strong>.</p><ul><li>Pour un ulcère duodénal (UD) ou dépistage : <strong>test respiratoire à l'urée marquée</strong>.</li><li>Pour un ulcère gastrique (UG) : <strong>contrôle endoscopique impératif</strong> avec biopsies de la zone cicatricielle.</li></ul>"},{"i":"9654c8aefb25","n":272,"o":"272-15","u":"Prise en charge","t":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","q":"Quels sont les principaux schémas d'éradication d'<i>Helicobacter pylori</i> et leurs indications ?","a":"<p>Les principaux schémas d'éradication d'<i>H. pylori</i> sont :</p><ul><li><strong>Quadrithérapie bismuthée (10 jours)</strong> : métronidazole + tétracycline + oméprazole double dose + sous-citrate de bismuth. Indiquée en cas d'allergie aux β-lactamines, sensibilités non connues, ou résistance à la clarithromycine et lévofloxacine.</li><li><strong>Quadrithérapie concomitante (14 jours)</strong> : métronidazole + amoxicilline + clarithromycine + IPP double dose. Indiquée en cas de sensibilités non connues, sans allergie aux β-lactamines.</li><li><strong>Trithérapie concomitante (10 jours)</strong> : amoxicilline + IPP double dose + clarithromycine (ou lévofloxacine si résistance). Indiquée si sensibilité connue, sans allergie aux β-lactamines.</li></ul>"},{"i":"fcac2982c1b1","n":272,"o":"272-15","u":"Prise en charge","t":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","q":"Quels sont les objectifs du traitement de l'ulcère gastroduodénal (UGD) non compliqué ?","a":"<p>Les objectifs du traitement de l'UGD non compliqué sont :</p><ul><li>Suppression rapide des symptômes.</li><li>Cicatrisation de l'ulcère.</li><li>Prévention des récidives.</li><li>Prévention des complications.</li></ul>"},{"i":"4b0e12070007","n":272,"o":"272-16","u":"Définition","t":"Connaître la définition d'une gastrite","q":"Comment poser le diagnostic histologique de la gastrite ?","a":"<p>Le diagnostic histologique de gastrite nécessite de réaliser <strong>5 biopsies</strong> lors de l'endoscopie :</p><ul><li><strong>2 au niveau du fundus</strong></li><li><strong>2 au niveau de l'antre gastrique</strong></li><li><strong>1 au niveau de l'angle de la petite courbure</strong></li></ul>"},{"i":"6cc25d85a7f6","n":272,"o":"272-16","u":"Définition","t":"Connaître la définition d'une gastrite","q":"Comment distinguer une gastrite d'une gastropathie ?","a":"<p>La <strong>gastrite</strong> est caractérisée par un <strong>infiltrat inflammatoire</strong> de la muqueuse gastrique. La <strong>gastropathie</strong> est une affection diffuse de la muqueuse gastrique, mais <strong>sans infiltrat inflammatoire</strong>.</p>"},{"i":"91d990086d73","n":272,"o":"272-16","u":"Définition","t":"Connaître la définition d'une gastrite","q":"Quelle est la particularité de la corrélation entre les signes cliniques, l'aspect endoscopique et l'histologie d'une gastrite ?","a":"<p>Il n'existe <strong>aucune corrélation</strong> entre l'histologie d'une gastrite et la symptomatologie clinique ou l'aspect endoscopique. Le terme « gastrite » est un <strong>diagnostic purement histologique</strong>.</p>"},{"i":"9a6c0c064687","n":272,"o":"272-16","u":"Définition","t":"Connaître la définition d'une gastrite","q":"Quelle est la définition histologique d'une gastrite ?","a":"<p>Une gastrite est définie histologiquement par des <strong>lésions inflammatoires aiguës ou chroniques de la muqueuse gastrique</strong>.</p>"},{"i":"0d24654e9aed","n":272,"o":"272-6","u":"Diagnostic positif","t":"Connaître les caractéristiques/sémiologie de la douleur de l'ulcère","q":"Quelles sont les caractéristiques de la douleur typique de l'ulcère gastroduodénal et comment évolue-t-elle au cours de la journée ?","a":"<p>La douleur typique de l'ulcère gastroduodénal est <strong>épigastrique</strong>, à type de <strong>crampe</strong>, de <strong>torsion</strong> ou de <strong>faim douloureuse</strong>.</p><ul><li>Elle est <strong>calmée par la prise d'aliments</strong>, d'anti-acides et de pansements gastriques.</li><li>Elle présente une <strong>périodicité diurne</strong> : douleur <strong>post-prandiale tardive</strong>, survenant 1 à 3 heures après les repas.</li></ul>"},{"i":"c23c82fe8a81","n":272,"o":"272-6","u":"Diagnostic positif","t":"Connaître les caractéristiques/sémiologie de la douleur de l'ulcère","q":"Quelles sont les particularités et pièges du syndrome douloureux atypique de l'ulcère gastroduodénal ?","a":"<p>Le syndrome douloureux atypique de l'ulcère gastroduodénal peut présenter :</p><ul><li>Une <strong>localisation variable</strong> (hypochondre droit, gauche, irradiation dorsale ou strictement postérieure).</li><li>Une <strong>intensité variable</strong> (forme hyperalgique pseudo-chirurgicale ou simple gêne frustre).</li><li>Une <strong>absence de périodicité</strong>, la douleur n'est pas rythmée par l'alimentation.</li></ul><p>Le piège est que le <strong>syndrome douloureux atypique est plus fréquent que la forme typique</strong>.</p>"},{"i":"db44a2185abc","n":272,"o":"272-6","u":"Diagnostic positif","t":"Connaître les caractéristiques/sémiologie de la douleur de l'ulcère","q":"Comment la douleur typique de l'ulcère gastroduodénal évolue-t-elle au cours de l'année ?","a":"<p>La douleur typique de l'ulcère gastroduodénal présente une <strong>double périodicité</strong>, incluant une périodicité annuelle :</p><ul><li>Elle se manifeste par des <strong>poussées de quelques semaines</strong>.</li><li>Ces poussées sont séparées par des <strong>intervalles asymptomatiques</strong> de quelques mois à plusieurs années.</li></ul>"},{"i":"7a0e34d98e86","n":272,"o":"272-7","u":"Examens complémentaires","t":"Connaître les indications de l'endoscopie haute devant une douleur ulcéreuse","q":"Pourquoi la réalisation d'une endoscopie digestive haute (EOGD) est-elle indispensable pour diagnostiquer un ulcère gastroduodénal ?","a":"<p>L'EOGD est indispensable car :</p><ul><li>Elle <strong>affirme le diagnostic</strong> d'ulcère, qui ne peut pas reposer uniquement sur les symptômes.</li><li>Elle permet d'<strong>éliminer les diagnostics différentiels</strong>, notamment un <strong>cancer</strong> en cas d'ulcère gastrique.</li><li>Elle offre la possibilité de réaliser des <strong>biopsies</strong> en cas de nécessité.</p></ul>"},{"i":"8a70d6a3998c","n":272,"o":"272-7","u":"Examens complémentaires","t":"Connaître les indications de l'endoscopie haute devant une douleur ulcéreuse","q":"Quelles sont les indications de l'endoscopie digestive haute (EOGD) chez un patient présentant une douleur ulcéreuse ?","a":"<p>Une EOGD est indiquée devant une douleur ulcéreuse dans les cas suivants :</p><ul><li>Âge <strong>supérieur à 50 ans</strong>.</li><li>Présence de <strong>signes d'alarme</strong> : dysphagie, amaigrissement, hémorragie digestive, anémie.</li><li><strong>Inefficacité du traitement symptomatique de première intention</strong>.</li></ul>"},{"i":"9a3246b5894a","n":272,"o":"272-7","u":"Examens complémentaires","t":"Connaître les indications de l'endoscopie haute devant une douleur ulcéreuse","q":"Quelle est la particularité de la conduite à tenir biopsique et du suivi endoscopique entre un ulcère duodénal et un ulcère gastrique ?","a":"<p>La conduite à tenir diffère selon le siège :</p><ul><li><strong>Ulcère duodénal</strong> : <strong>pas de biopsie</strong> de la lésion duodénale elle-même. Des biopsies gastriques (antre, angle, fundus) sont réalisées pour rechercher <em>Helicobacter pylori</em>. Le contrôle endoscopique n'est pas systématique si le patient est asymptomatique, sauf en cas d'ulcère duodénal compliqué.</li><li><strong>Ulcère gastrique</strong> : biopsies <strong>systématiques des berges de l'ulcère</strong> (<strong>6 à 12 biopsies</strong>) pour rechercher un adénocarcinome ou un lymphome, en plus des biopsies gastriques pour <em>H. pylori</em>. Une <strong>fibroscopie de contrôle</strong> est nécessaire après traitement.</li></ul><p>Dans <strong>tout ulcère gastroduodénal</strong>, la recherche de <em>H. pylori</em> est <strong>systématique</strong>.</p>"},{"i":"b41fa92c6d66","n":272,"o":"272-7","u":"Examens complémentaires","t":"Connaître les indications de l'endoscopie haute devant une douleur ulcéreuse","q":"Quel aspect endoscopique est caractéristique d'un ulcère gastroduodénal et quel piège diagnostique doit être connu ?","a":"<p>L'aspect endoscopique typique d'un ulcère est :</p><ul><li>Une <strong>perte de substance profonde « creusante »</strong>.</li><li>Un fond <strong>pseudo-membraneux blanchâtre</strong>, parfois nécrotique.</li><li>Une lésion <strong>ronde ou ovalaire</strong>, à bords <strong>réguliers, surélevés et érythémateux</strong>.</li></ul><p>Un <strong>ulcère duodénal post-bulbaire</strong> (très rare) doit faire évoquer un <strong>syndrome de Zollinger-Ellison</strong> ou une <strong>MICI</strong> (Maladie de Crohn, vascularite).</p>"},{"i":"08801bfb4b41","n":272,"o":"272-8","u":"Examens complémentaires","t":"Savoir prescrire une recherche d'HP (tests invasifs et non invasifs)","q":"Quel est le piège classique à éviter concernant les biopsies pour la recherche d'<i>Helicobacter pylori</i>, notamment dans le contexte d'un ulcère hémorragique ?","a":"<p>Il ne faut <strong>jamais réaliser de biopsies duodénales</strong> pour la recherche d'HP ; seules les biopsies gastriques (antrales et fundiques) sont valides.</p><p>Devant un <strong>ulcère hémorragique</strong>, les biopsies ne sont pas réalisables en période hémorragique ; c'est alors la <strong>sérologie</strong> qui est indiquée pour rechercher l'HP.</p>"},{"i":"78554b27b1d0","n":272,"o":"272-8","u":"Examens complémentaires","t":"Savoir prescrire une recherche d'HP (tests invasifs et non invasifs)","q":"Dans quel contexte clinique doit-on systématiquement rechercher <i>Helicobacter pylori</i> (HP) d'après le contenu source ?","a":"<p>La recherche d'<i>H. pylori</i> est systématique devant :</p><ul><li>Tout <strong>ulcère gastroduodénal (UGD)</strong>.</li><li>Tout <strong>cancer de l'estomac</strong>.</li><li>Des <strong>facteurs de risque</strong> de cancer gastrique (apparenté du 1er degré, syndrome de Lynch (HNPCC), ATCD de gastrectomie partielle, lésions prénéoplasiques : atrophie sévère, métaplasie intestinale, dysplasie).</li></ul>"},{"i":"ad6f765767a5","n":272,"o":"272-8","u":"Examens complémentaires","t":"Savoir prescrire une recherche d'HP (tests invasifs et non invasifs)","q":"Quels sont les tests invasifs et non invasifs pour la recherche d'<i>Helicobacter pylori</i>, et leurs principales caractéristiques ou indications spécifiques (selon le contenu) ?","a":"<ul><li><strong>Tests invasifs :</strong><ul><li><strong>Biopsies gastriques</strong> (antrales et fundiques) avec anatomopathologie, culture + antibiogramme ou PCR. C'est l'<strong>examen de référence</strong>, avec une Se & Sp &gt; 95%.</li></ul></li><li><strong>Tests non invasifs :</strong><ul><li><strong>Test respiratoire à l'urée marquée (C13)</strong> : Très performant (Se & Sp &gt; 95%), utile surtout pour le <strong>contrôle d'éradication</strong> et <strong>seul test remboursé</strong> pour ce contrôle.</li><li><strong>Recherche d'antigènes fécaux</strong> : Bonne performance (Se 91-96% / Sp 93-97%), utile avant traitement et pour le contrôle, mais <strong>non remboursé</strong>.</li><li><strong>Sérologie</strong> : Moins sensible et spécifique (Se 85% / Sp 79%), utile en cas d'<strong>hémorragie</strong> (où les biopsies sont impossibles), d'<strong>atrophie gastrique</strong> ou d'<strong>antibiothérapie récente</strong>. Elle <strong>reste positive après éradication</strong> et est donc inutile pour le contrôle.</li></ul></li></ul>"},{"i":"ca622937dcaa","n":272,"o":"272-8","u":"Examens complémentaires","t":"Savoir prescrire une recherche d'HP (tests invasifs et non invasifs)","q":"Selon la HAS, en dehors des situations systématiques, dans quelles autres situations spécifiques la recherche d'<i>Helicobacter pylori</i> est-elle recommandée ?","a":"<p>La HAS recommande la recherche d'<i>H. pylori</i> avant de débuter un traitement par <strong>AINS</strong> ou <strong>aspirine</strong> si le patient a des antécédents d'UGD, et en cas de :</p><ul><li>Carence martiale <strong>inexpliquée</strong>.</li><li>Carence en <strong>B12</strong> sans cause identifiée.</li><li>Lymphome gastrique du <strong>MALT</strong>.</li><li>Avant un <strong>by-pass gastrique</strong>.</li><li>Purpura thrombopénique immunologique (PTI) de l'adulte.</li></ul>"},{"i":"35d129560508","n":272,"o":"272-9","u":"Identifier une urgence","t":"Savoir reconnaître les signes de gravité d'une douleur ulcéreuse","q":"Quelle est l'importance de l'intensité de la douleur ulcéreuse pour juger de sa gravité ?","a":"<p>L'intensité de la douleur ulcéreuse n'a <strong>aucun caractère prédictif de gravité</strong> et l'on ne retrouve pas de parallélisme anatomo-clinique. Il n'existe <strong>aucun critère de gravité de la douleur ulcéreuse elle-même</strong>.</p>"},{"i":"6bbd636e3d9b","n":272,"o":"272-9","u":"Identifier une urgence","t":"Savoir reconnaître les signes de gravité d'une douleur ulcéreuse","q":"Quels sont les signes cliniques qui doivent faire rechercher une éventuelle dégénérescence en cancer chez un patient présentant une douleur ulcéreuse ?","a":"<p>Devant une douleur ulcéreuse, l'existence d'un <strong>amaigrissement</strong> ou d'une <strong>adénopathie sus-claviculaire</strong> (ganglion de Troisier) doit faire suspecter et rechercher une dégénérescence en cancer.</p>"},{"i":"9bc169064e4d","n":272,"o":"272-9","u":"Identifier une urgence","t":"Savoir reconnaître les signes de gravité d'une douleur ulcéreuse","q":"Quels sont les signes cliniques qui doivent faire rechercher une perforation dans le contexte d'une douleur ulcéreuse ?","a":"<p>Face à une douleur ulcéreuse, la présence d'une <strong>défense</strong> ou d'une <strong>contracture abdominale</strong> doit faire évoquer et rechercher une perforation.</p>"},{"i":"f62a036e5a6c","n":272,"o":"272-9","u":"Identifier une urgence","t":"Savoir reconnaître les signes de gravité d'une douleur ulcéreuse","q":"Quels sont les signes cliniques qui doivent faire rechercher une hémorragie digestive dans le contexte d'une douleur ulcéreuse ?","a":"<p>En présence d'une douleur ulcéreuse, l'apparition des signes suivants doit faire rechercher une hémorragie :</p><ul><li><strong>Chute tensionnelle</strong></li><li><strong>Tachycardie</strong></li><li><strong>Hématémèse</strong> ou <strong>méléna</strong></li><li>Présence de <strong>sang au toucher rectal</strong></li></ul>"}]};